INSERT INTO `catalog` (`id`, `title`, `slug`, `type`, `short_description`, `category_id`, `brand_id`, `product_id`, `file`, `thumbnail`, `status`, `ancestor_id`, `created_at`, `updated_at`) VALUES
('648182240ec63-ctlg-93460437567543138', '2017 Lang Workholding Catalogue', 'catalogue-lang-2017-lang-workholding-catalogue', 'catalogue', '2017 catalogue for some of Lang\'s most popular work holding solutions, which are still in high demand among customers.', '65115eaa217bc-ctgr-80906052148787198', '1', NULL, '2017-Lang-Workholding-Catalogue-MTS.pdf', '170290332365803e1bda139Screenshot 2023-12-18 183558.png', 1, NULL, '2023-06-08 01:24:20', '2024-04-04 00:38:45'),
('6543583c549bd-ctlg-53271021388606610', 'Lang Workholding', 'catalogue-lang-lang-workholding', 'catalogue', 'LANG\'s WorkHolding solutions with all new & updated products from 2022 to provide you with maximum process reliability.', '65115eaa217bc-ctgr-80906052148787198', '1', NULL, 'Lang-Workholding-Catalogue-MTS.pdf', '16989123156543583be1ec6Screenshot 2023-11-02 140024.png', 1, NULL, '2023-11-02 15:05:16', '2024-05-10 23:53:11'),
('654375e6034ed-ctlg-19037940351209661', 'OK-VISE E-catalogue', 'catalogue-ok-vise-ok-vise-e-catalogue', 'catalogue', 'OK-Vise provides you with variety of clamping options with their unique & revolutionary Low-Profile Clamping Fixtures.', '6572a24b578c9-ctgr-53848849091679278', '653b46614148c-brnd-14428085574324353', NULL, '1698919910654375e600e2dok-vise_fc_2016v1eng_low-MTS.pdf', '1698919910654375e600b37Screenshot_28.png', 1, NULL, '2023-11-02 17:11:50', '2024-04-05 02:18:50'),
('654382323a6de-ctlg-77484143179822082', 'PINTEC E-Catalogue', 'catalogue-pintec-pintec-e-catalogue', 'catalogue', 'Your go-to CMM solution, Pintec\'s modular mold clamping system can be combined & expanded for your requirements.', '65aaba8fc0b16-ctgr-83259238588199759', '653b40ed2bbbd-brnd-56085618647099342', '65fb3021b109a-prod-39924558909810568', '170534317965a578cba1af2pintec-MTS-product_catalog_2021-03_s.pdf', '170551707265a82010bab6apintec Thumbnail.png', 1, NULL, '2023-11-02 18:04:18', '2024-04-05 02:20:16'),
('65439c458bdc4-ctlg-13778079566131462', 'Vise In-Row', 'catalogue-ok-vise-vice-in-row-e-catalogue', 'catalogue', 'Adjustable Clamping System that can clamp square, round or irregularly shaped working pieces, saves mold changing time & cost.', '6572a24b578c9-ctgr-53848849091679278', '653b46614148c-brnd-14428085574324353', NULL, '169892973365439c458b963E-catalogue-MTS-HRV-VICES.pdf', '169892973365439c458b6f2Screenshot_30.png', 1, NULL, '2023-11-02 19:55:33', '2024-04-05 21:14:55'),
('65439d0aaeed2-ctlg-53751412980993867', 'AR Filtrazioni Product Catalogue', 'catalogue-ar-filtrazioni-ar-filtrazioni-e-catalogue', 'catalogue', 'AR Filtrazioni catalogue containing all series of filtration products provided by AR Filtrazioni for different pollutants.', '6576d5a741b95-ctgr-63855707496093227', '653b4579b3e3b-brnd-38786264451941358', '6576d65497f3f-prod-42278584952552023', 'AR-Filtrazioni-E-Catalogue-MTS.pdf', '169892993065439d0aad0d4Screenshot_1.png', 1, NULL, '2023-11-02 19:58:50', '2024-04-05 21:33:01'),
('6544e2a5d74ec-ctlg-20974480645031358', 'Zero-Point Clamping', 'catalogue-lang-workholding-zeropoint', 'catalogue', 'LANG\'s Zero-Point Clamping solution(2022) has a wide customization option, extremely user friendly, and the shortest set-up time.', '65115ed015bd9-ctgr-97049127326775050', '1', '6512a94cb4fca-prod-43649400206378705', 'Lang-Zero-Point-Clamping-Catalogue-MTS.pdf', '16990132856544e2a5d6ea2Screenshot_4.png', 1, NULL, '2023-11-03 19:08:05', '2024-05-21 01:14:30'),
('6544e422a9e27-ctlg-68026343640751131', 'Lang Automation', 'catalogue-lang-lang-automation', 'catalogue', 'LANG\'s Automation System from 2022 covers every need from single part or large-scale production. They are uncomplicated, flexible, and offer best value for money.', '65115ef3de69d-ctgr-19924755263429886', '1', NULL, 'Lang-Automation-Catalogue-MTS.pdf', '16990136666544e422a96c3Screenshot_5.png', 1, NULL, '2023-11-03 19:14:26', '2024-04-04 01:42:42'),
('6544e6b12b92c-ctlg-81483923346776037', 'S.P.D Electro-Permanent Magnet for Grinding', 'catalogue-spd-mts-spd-electro-permanent-for-griding', 'catalogue', 'Electro-Permanent Magnetic Workholding Solutions from S.P.D is the most effective way of clamping work-pieces with less energy & no overheating during operation.', '65328299b15dd-ctgr-27302527109501547', '653b407814c5d-brnd-30399065672704514', NULL, 'MTS-SPD-ELECTRO-PERMANENT FOR GRIDING.pdf', '16990143216544e6b12b3b6Screenshot_6.png', 1, NULL, '2023-11-03 19:25:21', '2024-04-05 01:57:22'),
('6544e77376ac6-ctlg-47396202602134081', 'S.P.D Battery Powered Lifting', 'catalogue-spd-mts-spd-electropremanent-lifting-battery-magnets-sb01', 'catalogue', 'S.P.D\'s Battery Powered Lifting is similar to Electro-Permanent Lifters but provides you even more convenience & accessibility.', '65328299b15dd-ctgr-27302527109501547', '653b407814c5d-brnd-30399065672704514', NULL, '16990145156544e7737680aMTS-SPD-Electropremanent-Lifting-Battery-Magnets-SB01.pdf', '16990145156544e77376537Screenshot_7.png', 1, NULL, '2023-11-03 19:28:35', '2024-04-05 02:09:29'),
('6544e8708258a-ctlg-20746053215675215', 'S.P.D Permanent Lifting Magnets', 'catalogue-spd-mts-spd-permanent-lifting', 'catalogue', 'S.P.D\'s Permanent Lifting Magnets are reliable with greater sturdiness, greater compactness, & increased force.', '65328471c311f-ctgr-62324388771040640', '653b407814c5d-brnd-30399065672704514', NULL, '16990147686544e87081a9bMTS-SPD-Permanent_Lifting-_Magnets-1.pdf', '16990147686544e870818c5Screenshot_8.png', 1, NULL, '2023-11-03 19:32:48', '2024-04-05 20:35:32'),
('6544e96bedca8-ctlg-68756934007664813', 'S.P.D Electropermanent Chucks With Radial Poles', 'catalogue-spd-mts-spd-radial-eng-ita-2009', 'catalogue', 'Special electro-permanent chucks suitable for grinding, turning, machining of rings/ circular work-pieces even of big dimension.', '65328299b15dd-ctgr-27302527109501547', '653b407814c5d-brnd-30399065672704514', NULL, 'MTS-SPD-Radial-ENG- ITA-2009.pdf', '16990150196544e96bed4b3Screenshot_9.png', 1, NULL, '2023-11-03 19:36:59', '2024-04-05 20:47:45'),
('6544eaa193923-ctlg-85114356836069262', 'S.P.D Electro-permanent Telescopic Beam - TRETEL', 'catalogue-spd-mts-spd-tretel', 'catalogue', 'S.P.D\'s Electro-Permanent Magnetic TRETEL system is well renowned for its safety, reliability, swiftness and user-friendliness.', '65328471c311f-ctgr-62324388771040640', '653b407814c5d-brnd-30399065672704514', NULL, 'MTS-SPD-TRETEL_ EN-1.pdf', '16990153296544eaa193275Screenshot_10.png', 1, NULL, '2023-11-03 19:42:09', '2024-04-05 20:53:52'),
('6544eb2ec6a84-ctlg-68873311284751741', 'S.P.D Grinding Chucks', 'catalogue-spd-spd-mts-griding-chucks', 'catalogue', 'S.P.D\'s Electro-Permanent Grinding System - Long pole magnetic chucks for safe & fast magnetic blocking, tailored to your request.', '65328299b15dd-ctgr-27302527109501547', '653b407814c5d-brnd-30399065672704514', NULL, 'SPD-MTS-Griding chucks E-catalogue.pdf', '16990154706544eb2ec60c3Screenshot_11.png', 1, NULL, '2023-11-03 19:44:30', '2024-04-05 20:58:30'),
('65453c31cdc46-ctlg-91208777296206854', 'S.P.D Electro-Permanent Milling System.', 'catalogue-spd-milling-electro-permanent-system', 'catalogue', 'S.P.D\'s Electro-Permanent Milling Systems offers advantages like safety, no energy, perfect locking, free working surface, etc.', '65328299b15dd-ctgr-27302527109501547', '653b407814c5d-brnd-30399065672704514', NULL, '169903620965453c31ccbf7MTS-SPD-MILLING-ELECTRO-PERMANENT-SYSTEM.pdf', '169903620965453c31cca35milling.png', 1, NULL, '2023-11-04 01:30:09', '2024-04-05 21:08:41'),
('654b6f1a6d434-ctlg-32249218384059248', 'AutoGrip - Turning Solutions E-Catalogue', 'catalogue-autogrip-autogrip-tuning-solutions-e-catalogue', 'catalogue', 'Autogrip catalogue for power chucks, Rotary Cylinders, & Clamping Series which are used in Turning Solutions worldwide.', '6572b24359595-ctgr-12814737465481327', '653b40cbb988a-brnd-61212735378470921', NULL, 'AUTOGRIP_CATALOGUE 2020.09EN_MTS (1).pdf', '1699442458654b6f1a6ce5aScreenshot_12.png', 1, NULL, '2023-11-08 18:20:58', '2024-04-04 02:07:06'),
('654b7097d2ddf-ctlg-55065409998957338', 'BRISC Permanent Lifting Magnets', 'catalogue-spd-brisc-permanent-lifting-magnets', 'catalogue', 'BRISC\'s PLM series provides you with a wide range of permanent lifting magnet options from Light lifting to Heavy lifting for your specific needs.', '65328471c311f-ctgr-62324388771040640', '653b45a8bdc8e-brnd-66640211787984589', NULL, 'PLM-01-EN-MTS-2014.pdf', '1699442839654b7097d25beScreenshot_13.png', 1, NULL, '2023-11-08 18:27:19', '2024-04-05 02:17:10'),
('6580486a9f993-ctlg-90137212817494492', 'Lang 2023 New Products', 'catalogue-lang-lang-2023-new-products', 'catalogue', 'The latest catalogue of Lang products from 2023 with brand new patented system & products to provide you with more stronger and secure work holding solutions.', '65115eaa217bc-ctgr-80906052148787198', '1', NULL, 'Lang-2023-New-Products-Catalogue-MTS.pdf', '17029059626580486a9eaabScreenshot 2023-12-18 191350.png', 1, NULL, '2023-12-18 20:26:02', '2024-04-04 01:22:57'),
('658dde6933952-ctlg-49509704599213041', 'Robotic Electro Permanent Magnetic Lifting Form', 'form-spd-robotic-electro-permanent-magnetic-lifting-form', 'form', 'Form for Robotic Electro Permanent Magnetic Lifting Application', '65328471c311f-ctgr-62324388771040640', '653b407814c5d-brnd-30399065672704514', NULL, '1703796329658dde6933794ROBOTIC ELECTROPERMANENT LIFTING MODULE QUESTIONNAIRE-x.pdf', '1703796649658ddfa920da5ROBOTIC-ELECTROPERMANENT-LIFTING thumbnail.jpg', 1, NULL, '2023-12-29 03:45:29', '2024-03-01 20:18:14'),
('65b4117ac4e92-ctlg-66660379458832547', 'Lang - Technique de serrage', 'catalogue-lang-lang-technique-de-serrage', 'catalogue', NULL, '65115eaa217bc-ctgr-80906052148787198', '1', NULL, '170629990065b411fc4e83d2022-04_lang_catalogue-workholding_FR_MTS_compressed.pdf', '170629977065b4117a5d527placeholder.jpg', 0, NULL, '2024-01-27 03:09:30', '2024-03-01 20:18:14'),
