INSERT INTO `product_attribute` (`id`, `type`, `is_filter`, `attribute_id`, `custom_field_id`, `sub_option`, `product_id`, `attribute_name`, `value`, `title`, `details`, `image`, `language_code`, `ancestor_id`, `created_at`, `updated_at`) VALUES
(765, 'custom value', 0, NULL, '3', 'Makro•Grip® FS Stamping Technology and Raw Part Clamping', '651cfeea67ace-prod-49529316546112245', NULL, NULL, NULL, 'The Makro•Grip® 5-Axis Vise and its unique benefits of the stamping technology has been considered „The Original“ and a benchmark in the 5-face machining of raw parts for years. Makro•Grip® FS is the further development of this product. Its compact design and high holding forces make the Makro•Grip® FS 5-Axis Vise the ideal clamping device for machining raw parts.', '', 'en', '764', '2023-10-04 13:06:05', '2023-10-04 13:06:05'),
(766, 'custom value', 0, NULL, '3', 'Makro•Grip® FS Stamping Technology and Raw Part Clamping', '651cfeea67ace-prod-49529316546112245', NULL, NULL, 'Holding force', 'Thanks to a new stamping and holding serration, up to 60% higher holding forces can be achieved with Makro•Grip® FS.', '', 'en', '764', '2023-10-04 13:06:05', '2023-10-04 13:06:05'),
(767, 'custom value', 0, NULL, '3', 'Makro•Grip® FS Stamping Technology and Raw Part Clamping', '651cfeea67ace-prod-49529316546112245', NULL, NULL, 'Process reliability', 'Clamping with Makro•Grip® FS offers maximum process reliability and allows even higher cutting rates and faster milling processes.', '', 'en', '764', '2023-10-04 13:06:05', '2023-10-04 13:06:05'),
(768, 'custom value', 0, NULL, '3', 'Makro•Grip® FS Stamping Technology and Raw Part Clamping', '651cfeea67ace-prod-49529316546112245', NULL, NULL, 'Accessibility', 'The compact Makro•Grip® FS self-centering vises guarantee ideal accessibility in the 5-axis machining of raw parts.', '', 'en', '764', '2023-10-04 13:06:05', '2023-10-04 13:06:05'),
