INSERT INTO `product_part` (`id`, `name`, `slug`, `code`, `parts_type`, `brand_id`, `product_id`, `price`, `key_features`, `further_information`, `discount_type`, `discount`, `thumbnail`, `images`, `status`, `ancestor_id`, `short_number`, `created_at`, `updated_at`) VALUES
('65a227b636bfe-pprt-89497772175826729', 'Makro•Grip®, Assembly Tool for magnets', '48420-lang-makrogrip-assembly-tool-for-magnets', '48420', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The assembly tool is required for mounting and removing the magnets in the first generation of Makro•Grip® contour jaws. In the meantime, contour jaws are already supplied with mounted magnets.</p>', '<p><br></p>', NULL, NULL, '170512581465a227b6369f548420[1]_1.webp', NULL, 1, NULL, 0, '2024-01-13 13:03:34', '2024-03-01 20:17:35'),
('65a22c7d1093e-pprt-20356038742250174', 'Avanti 125, Center Base Jaw + Spindle', '44355-tg125-lang-avanti-125-center-base-jaw-spindle', '44355-TG125', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">If required, the Avanti vise can be converted into a multiple clamp. During the conversion, which can be carried out in a few moments, only the set of spindle + center piece from the contour clamp has to be replaced by the center base jaw + spindle. For (multiple) workpiece clamping, the same top jaw as for the base jaws is mounted on the center base jaw.</p>', '<p><br></p>', NULL, NULL, '170512703765a22c7d103bd44355-TG125[1].webp', '[\"170512703765a22c7d1068044355-TG125_Seite_2.webp\",\"170512703765a22c7d107dc44355-TG125_Seite_1.webp\"]', 1, NULL, 0, '2024-01-13 13:23:57', '2024-03-01 20:17:35'),
