('65a50e035c4d5-pprt-58004291495772672', 'Makro•Grip® 77, Spindle Cover', '47077-70-lang-makrogrip-77-spindle-cover', '47077-70', 'parts', '1', NULL, 1.00, '<p><br></p>', '<p><br></p>', NULL, NULL, '170531584365a50e035c347placeholder.png', NULL, 1, NULL, 0, '2024-01-15 17:50:43', '2024-03-01 20:17:35'),
('65a50e862a7a0-pprt-43424931952085874', 'Makro•Grip® 77, Spindle Cover', '47077-80-lang-makrogrip-77-spindle-cover', '47077-80', 'parts', '1', NULL, 1.00, '<p><br></p>', '<p><br></p>', NULL, NULL, '170531597465a50e862a5d6placeholder.png', NULL, 1, NULL, 0, '2024-01-15 17:52:54', '2024-03-01 20:17:35'),
('65a50eff8c719-pprt-21214497440993859', 'Makro•Grip® 125, Spindle Cover', '47125-70-lang-makrogrip-125-spindle-cover', '47125-70', 'parts', '1', NULL, 1.00, '<p><br></p>', '<p><br></p>', NULL, NULL, '170531609565a50eff8c541placeholder.png', NULL, 1, NULL, 0, '2024-01-15 17:54:55', '2024-03-01 20:17:35');
INSERT INTO `product_part` (`id`, `name`, `slug`, `code`, `parts_type`, `brand_id`, `product_id`, `price`, `key_features`, `further_information`, `discount_type`, `discount`, `thumbnail`, `images`, `status`, `ancestor_id`, `short_number`, `created_at`, `updated_at`) VALUES
('65a510c765eb6-pprt-32579408934764655', 'Makro•Grip® Ultra, Stamping Jaws', '41112-06-lang-makrogrip-ultra-stamping-jaws', '41112-06', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">These high-end stamping jaws are specially designed for use with the Makro-Grip® Ultra stamping unit and are supplied without support bars. Depending on which jaws are mounted on the Makro-Grip® Ultra system, the user can freely decide whether to mount parallels with a clamping depth of 3 mm (item no. 41111-0308) or with a clamping depth of 5 mm (item no. 41111-0508). These are available separately.</p>', '<p><br></p>', NULL, NULL, '170531655165a510c765b4141112-06[1].webp', '[\"170531655165a510c765d2941112-06_Seite_1[1].webp\"]', 1, NULL, 0, '2024-01-15 18:02:31', '2024-03-01 20:17:35'),
('65a5122487fdc-pprt-16329921193034497', 'Makro•Grip® Ultra, Parallels', '41111-0308-lang-makrogrip-ultra-parallels', '41111-0308', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">These parallels with a thickness of 8 mm are especially suitable for pre-stamping large workpieces with the Makro-Grip® Ultra stamping unit. The clamping depth is 3 mm (suitable for clamping jaws with item no. 81483).</p>', '<p><br></p>', NULL, NULL, '170531690065a5122487d0041111-0308[1].webp', '[\"170531690065a5122487ea041111-0308_Seite_1[1].webp\"]', 1, NULL, 0, '2024-01-15 18:08:20', '2024-03-01 20:17:35'),
('65a5189fabe1b-pprt-49343963496920412', 'Makro•Grip® Ultra, Parallels', '41111-0508-lang-makrogrip-ultra-parallels', '41111-0508', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">These parallels with a thickness of 8 mm are specially suitable for pre-stamping large workpieces with the Makro•Grip® Ultra stamping unit. The clamping depth is 5 mm (suitable for clamping jaws with item no. 81485).</p>', '<p><br></p>', NULL, NULL, '170531855965a5189fab9f341111-0508[1].webp', '[\"170531855965a5189fabc5341111-0508_Seite_1[1].webp\"]', 1, NULL, 0, '2024-01-15 18:35:59', '2024-03-01 20:17:35'),
('65a519e2280dd-pprt-66488020933185852', 'Makro•Grip® Ultra, Hexagon Socket', '45511-lang-makrogrip-ultra-hexagon-socket', '45511', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The hexagon socket size 19 mm can be used to clamp the workpieces in the Makro•Grip® Ultra clamping system. Its 1/2” square drive fits standard torque wrenches. The maximum tightening torque of the Makro•Grip® Ultra spindle unit is 170 Nm.</p>', '<p><br></p>', NULL, NULL, '170531888265a519e227ea245509.webp', NULL, 1, NULL, 0, '2024-01-15 18:41:22', '2024-03-01 20:17:35'),
('65a528fe44e90-pprt-81039581657713721', 'Makro•Grip® Ultra, Wrench', '45519-lang-makrogrip-ultra-wrench', '45519', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The wrench with external hexagon and a size of 19 mm can be used for the initial clamping setting in the Makro•Grip® Ultra system. This wrench is already included in the scope of delivery of the Makro•Grip® Ultra base sets. However, the final clamping of the workpieces should be done with a torque wrench.</p>', '<p><br></p>', NULL, NULL, '170532275065a528fe44c2f45501.webp', NULL, 1, NULL, 0, '2024-01-15 19:45:50', '2024-03-01 20:17:35'),
('65a529ad59dc0-pprt-48237410740885293', 'Makro•Grip® Ultra, Hexagon Socket', '45511-lang-makrogrip-ultra-hexagon-socket-2', '45511', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The hexagon socket size 19 mm can be used to clamp the workpieces in the Makro•Grip® Ultra clamping system. Its 1/2” square drive fits standard torque wrenches. The maximum tightening torque of the Makro•Grip® Ultra spindle unit is 170 Nm.</p>', '<p><br></p>', NULL, NULL, '170532292565a529ad59bc345509 (1).webp', NULL, 1, NULL, 0, '2024-01-15 19:48:45', '2024-03-01 20:17:35'),
('65a52a8cad121-pprt-88124379708574293', 'Makro•4Grip, Stamping Jaws', '51111-lang-makro4grip-stamping-jaws', '51111', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The Makro•4Grip stamping jaws, which enable the pre-stamping of round blanks, are compatible with all versions of the stamping unit. Two stamping inserts are mounted on each Makro•4Grip stamping jaw, with which the workpiece is stamped. In order to adapt the stamping inserts to different workpiece diameters or clamping jaw sizes, the stamping inserts are positioned at a total of three possible distances (narrow, medium, wide) from each other.</p>', '<p><br></p>', NULL, NULL, '170532314865a52a8cacdde51111[1].webp', '[\"170532314865a52a8cacfc051111_Seite_1.webp\"]', 1, NULL, 0, '2024-01-15 19:52:28', '2024-03-01 20:17:35'),
('65a52b8044cd4-pprt-20802779460938925', 'Makro•4Grip, Stamping Inserts', '51111-40-lang-makro4grip-stamping-inserts', '51111-40', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Round blanks are pre-stamped with the stamping inserts and then held with Makro•4Grip clamping jaws by form-fit. Four stamping inserts are required per pair of stamping jaws. Each stamping insert has a total of three cutting edges. If one cutting edge is worn out, two others can be used by turning them by 120 degrees and reassembling them.</p>', '<p><br></p>', NULL, NULL, '170532339265a52b8044a6751111-40[1].webp', NULL, 1, NULL, 0, '2024-01-15 19:56:32', '2024-03-01 20:17:35'),
('65a52c45a057e-pprt-76873471037803464', 'Hydro•Sup, Spacer', '81523-lang-hydrosup-spacer', '81523', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">This spacer, in conjunction with the Hydro•Sup hydraulic screw jack, provides an additional support surface at a height of between 228 and 232 mm and is, therefore, suitable for the “L” system height of Makro•Grip® Ultra. Together with the Hydro•Sup, it serves to reduce possible vibrations in the machining process of protruding components.</p>', '<p><br></p>', NULL, NULL, '170532358965a52c459ff9881523[1].webp', '[\"170532358965a52c45a020e81523_Seite_3[1].webp\",\"170532358965a52c45a033581523_Seite_2[1].webp\",\"170532358965a52c45a043c81523_Seite_1[1].webp\"]', 1, NULL, 0, '2024-01-15 19:59:49', '2024-03-01 20:17:35'),
('65a52d56dc935-pprt-85562374145695831', 'Hydro•Sup, Spacer', '81515-lang-hydrosup-spacer', '81515', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">This spacer, in conjunction with the Hydro•Sup hydraulic screw jack, provides an additional support surface at a height of between 148 and 152 mm and is, therefore, suitable for the “M” system height of Makro•Grip® Ultra. Together with the Hydro•Sup, it serves to reduce possible vibrations in the machining process of protruding components.</p>', '<p><br></p>', NULL, NULL, '170532386265a52d56dc38481515[1].webp', '[\"170532386265a52d56dc5d181515_Seite_3[1].webp\",\"170532386265a52d56dc70481515_Seite_2[1].webp\",\"170532386265a52d56dc7e781515_Seite_1[1].webp\"]', 1, NULL, 0, '2024-01-15 20:04:22', '2024-03-01 20:17:35'),
('65a52e5f0d9da-pprt-72973285938758470', 'Hydro•Sup, Hydraulic Screw Jack', '81586-lang-hydrosup-hydraulic-screw-jack', '81586', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The hydraulic screw jack Hydro•Sup serves to reduce possible vibrations in the machining process of protruding components. With a height of 86 mm, it matches the lowest system height of Makro•Grip® Ultra base body height. Due to its pendulum support, it offers a support height between 85 and 89 mm. By using additional spacers, the total height of the M and L systems can be replicated.</p>', '<p><br></p>', NULL, NULL, '170532412765a52e5f0d46081586[1].webp', '[\"170532412765a52e5f0d69d81586_Seite_3[1].webp\",\"170532412765a52e5f0d7a481586_Seite_2[1].webp\",\"170532412765a52e5f0d89781586_Seite_1[1].webp\"]', 1, NULL, 0, '2024-01-15 20:08:47', '2024-03-01 20:17:35'),
('65a541e7becb2-pprt-76741314163955876', 'Makro•Grip® Ultra, Connection Plate', '81015-lang-makrogrip-ultra-connection-plate', '81015', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Connection plates are needed to connect Makro-Grip® Ultra bodies together. They are attached to the rear base body and have a fit on the outside to accommodate a sliding block mounted on the outer end of the front base body. They are already included with the 610 and 810 Base Sets.</p>', '<p><br></p>', NULL, NULL, '170532912765a541e7be62681015[1].png', NULL, 1, NULL, 0, '2024-01-15 21:32:07', '2024-03-01 20:17:35'),
('65a545804869e-pprt-31541056344043245', 'Makro•Grip® Ultra, Centering Plate', '81010-lang-makrogrip-ultra-centering-plate', '81010', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Centring plates are used to provide a precise fit for the spindle unit of Makro-Grip® Ultra. Two centring plates are required per clamping unit, which are attached to the inner ends of the base bodies. This version is required for centric single part clamping and is included in the scope of delivery of the Base Sets.</p>', '<p><br></p>', NULL, NULL, '170533004865a545804843581010[1].webp', NULL, 1, NULL, 0, '2024-01-15 21:47:28', '2024-03-01 20:17:35'),
('65a5463d202de-pprt-13232862562592496', 'Makro•Grip® Ultra, Centering Plate', '81040-lang-makrogrip-ultra-centering-plate', '81040', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Centring plates are used to ensure a precise fit of the spindle unit of Makro-Grip® Ultra. Two centring plates are required per clamping unit, which are attached to the inner ends of the base bodies. This version is required for compensating multiple clamping and is characterised by a milled recess which gives the spindle unit additional clearance for components of different sizes (max. 4 mm).</p>', '<p><br></p>', NULL, NULL, '170533023765a5463d2008881040[1].webp', NULL, 1, NULL, 0, '2024-01-15 21:50:37', '2024-03-01 20:17:35'),
('65a54c615aea4-pprt-60762083671876198', 'Makro•Grip® Ultra, Spindle Unit', '81006-lang-makrogrip-ultra-spindle-unit', '81006', 'parts', '1', NULL, 1.00, '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The spindle unit for the Makro•Grip® Ultra is simply fitted between two high-precision centering plates, which is why the system is set up very quickly. By removing the clamping jaws, the spindle unit can be removed upwards, which makes cleaning after (and between) production processes extremely easy and convenient.</p>', '<p><br></p>', NULL, NULL, '170533180965a54c615abdb81006[1].webp', '[\"170533180965a54c615ad5581006_Seite_1.webp\"]', 1, NULL, 0, '2024-01-15 22:16:49', '2024-03-01 20:17:35'),
