INSERT INTO `service` (`id`, `code`, `product_id`, `title`, `slug`, `short_description`, `description`, `url`, `media`, `additional_details`, `status`, `ancestor_id`, `created_at`, `updated_at`) VALUES
('65165cfd55772-srvs-19262356895495930', '13a6b6fed124', NULL, 'Repair and Refurbish', '13a6b6fed124-repair-and-refurbish', 'Magnetic chucks, lifters, and control units.', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\">Machine Tool Solutions Ltd. repairs and refurbishes magnetic chucks, lifters, and control units, including:</p><ul style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 20px; padding: 0px; direction: ltr; line-height: 1.6; list-style-position: outside;\"><li style=\"margin: 0px; padding: 0px; direction: ltr;\">Magnetic lifters with internal rotating shaft</li><li style=\"margin: 0px; padding: 0px; direction: ltr;\">Electro-permanent magnetic chucks for milling, grinding &amp; EDM</li><li style=\"margin: 0px; padding: 0px; direction: ltr;\">Control units for magnetic chucks</li><li style=\"margin: 0px; padding: 0px; direction: ltr;\">Electro-permanent magnetic lifters remote controlled/wired</li><li style=\"margin: 0px; padding: 0px; direction: ltr;\">Other magnetic products</li><li style=\"margin: 0px; padding: 0px; direction: ltr;\">Any manufacturer or brand name magnetic products</li></ul><h3 style=\"margin: 0.2em 0px 0.5em; padding: 0px; direction: ltr; text-rendering: optimizelegibility; line-height: 1.4;\"><font face=\"Lato, helvetica, arial, sans-serif\"><span style=\"font-size: 20px; font-family: Tahoma;\">Please CONTACT us to get a no obligation quote on custom made workholding solution.</span></font></h3><h3 style=\"margin: 0.2em 0px 0.5em; padding: 0px; direction: ltr; text-rendering: optimizelegibility; line-height: 1.4;\"><font face=\"Lato, helvetica, arial, sans-serif\"><span style=\"font-size: 20px; font-family: Tahoma;\">We can handle drawings in many formats including DWG, DXF, IGES, PDF and various SOLIDS formats.</span></font></h3>', NULL, '17014319476569ca8b67aff1696248435651ab27307259repair-and-refurbish_50.jpg', '[{\"description\":\"<p><br><\\/p>\",\"image\":\"\"}]', 1, NULL, '2023-09-29 12:13:33', '2024-03-01 20:18:14'),
('65165ee2aebcc-srvs-55053505575370516', '638ce913242c', NULL, 'Re-Certification', '638ce913242c-re-certification', 'Machine Tool Solutions Ltd. performs re-certification services of permanent magnetic lifters and conducts tests under controlled conditions.\r\n\r\nAs per O.H.S.A and Regulations for Industrial Establishments R.R.O.1990, Section #51, (R-28), A lifting device shall be thoroughly examined by a competent person to determine its capability of handling the maximum load as rated at least once a year and a permanent record shall be kept, signed by person doing the examination.', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\">Our technician performs internal preventive maintenance as well as test three times, using special equipment designed to determine the most accurate pulling force reading of magnetic lifter. Safety factor is also taken into consideration for re-certification record. In case when the pulling force is lower than required, an estimate cost of repair, if possible, will be quoted to the customer. Magnets inside the lifter would be replaced if required. Magnets will be cleaned, painted and labelled with updated new maximum load rating. The customer is given Load Certificate for his records. We strongly recommend re-certification of all magnet lifters at least once a year. Please contact us to how to expedite the service.<br></p>', NULL, '17014297346569c1e64e9001696337288651c0d88f26eerecertification-MTS_50.jpg', '[{\"description\":\"<p><br><\\/p>\",\"image\":\"\"}]', 1, NULL, '2023-09-29 12:21:38', '2024-03-01 20:18:14'),
('65165f339a091-srvs-57107017096684087', '18546b323a88', NULL, 'COMPONENTS MANUFACTURING OPTIMIZATION', '18546b323a88-components-manufacturing-optimization', 'Are your operations costing too much? Encountering consistent problems with bottlenecks, capacity, or quality issues? Do you need assistance with your continuous improvement mandate? Machine Tools Solutions Ltd. can effectively assist you', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\">With proper and thorough consultation with our work-holding equipments expert, we can cut your manufacturing costs! Processing capabilities include cell/fixture/gage design in addition to program optimization with clear vision on the “Big Picture”. Our experienced engineers have an uncanny ability to “see” improvement quickly, efficiently and provide the best solutions in a timely and professional manner. From managing OK-VISE low profile clamps to maximizing the utilization of Quick-Point grid plates applications, we have the professionals to guide you every step of the way. Let us cut your costs on metal working operations, NO RISK! We only receive payment upon your SAVING MONEY, so what do you have to lose?&nbsp;</p><h3 style=\"margin: 0.2em 0px 0.5em; line-height: 1.4; padding: 0px; direction: ltr; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\"><span style=\"font-size: 20px; font-family: Tahoma;\">Please CONTACT us to get a no obligation quote on custom made workholding solution.</span></font></h3><h3 style=\"margin: 0.2em 0px 0.5em; line-height: 1.4; padding: 0px; direction: ltr; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\"><span style=\"font-size: 20px; font-family: Tahoma;\">We can handle drawings in many formats including DWG, DXF, IGES, PDF and various SOLIDS formats.</span></font></h3>', NULL, '1696337397651c0df51c21aService-3.png', '[{\"description\":\"<p>With proper and thorough consultation with our work-holding equipments expert, we can cut your manufacturing costs! Processing capabilities include cell\\/fixture\\/gage design in addition to program optimization with clear vision on the \\u201cBig Picture\\u201d.<\\/p>\",\"image\":\"16992761926548e5a023ede_49778+49779.png\"},{\"description\":\"<p>With proper and thorough consultation with our work-holding equipments expert, we can cut your manufacturing costs!&nbsp;<\\/p>\",\"image\":\"16992761926548e5a024051_83420-HE_0.png\"}]', 1, NULL, '2023-09-29 12:22:59', '2024-03-01 20:18:14'),
('653b7ccb1fbb2-srvs-25716943780484432', '53402-LN', NULL, 'LANG CUSTOMIZATION AND REPAIR SERVICES', '53402-ln-lang-customization-and-repair-services', 'Modified clamping depth, Tungsten-carbide-coating, Modification of base.', '<p>- Modified clamping depth&nbsp;</p><p>- Tungsten-carbide-coating&nbsp;</p><p>- Modification of base&nbsp;</p>', NULL, '1701839138657001225ff701699419290654b149a7df59Product-Post_11zon.jpg', '[{\"description\":\"<p><br><\\/p>\",\"image\":\"\"}]', 1, NULL, '2023-10-27 16:03:07', '2024-03-01 20:18:14');
