INSERT INTO `translations` (`id`, `translatable_type`, `translatable_id`, `language_code`, `field`, `value`, `created_at`, `updated_at`) VALUES
(5, 'App\\Models\\Category', '646480e21ce2f-ctgr-52163769130437280', 'fr', 'title', 'AR FILTRAZIONI', '2023-07-10 00:22:52', '2023-07-10 00:41:13'),
(6, 'App\\Models\\Category', '646480e21ce2f-ctgr-52163769130437280', 'en', 'title', 'AR Filtrazioni', '2023-07-10 00:23:04', '2023-07-10 00:23:04'),
(7, 'App\\Models\\Service', '6475886833b2d-srvs-82683343231452381', 'fr', 'title', 'Optimisation de la fabrication des composants', '2023-07-10 00:51:06', '2023-07-10 01:18:49'),
(8, 'App\\Models\\Service', '6475886833b2d-srvs-82683343231452381', 'fr', 'short_description', 'Vos opérations vous coûtent trop cher ? Vous rencontrez des problèmes constants avec des goulots d\'étranglement, des problèmes de capacité ou de qualité ? Vous avez besoin d\'aide pour votre mandat d\'amélioration continue? Machine Tools Solutions Ltd. peut vous aider efficacement', '2023-07-10 00:51:06', '2023-07-10 01:18:49'),
(9, 'App\\Models\\Service', '6475886833b2d-srvs-82683343231452381', 'fr', 'description', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Avec une consultation appropriée et approfondie avec notre expert en équipements de maintien de travail, nous pouvons réduire vos coûts de fabrication ! Les capacités de traitement incluent la conception de cellule/fixation/jauge en plus de l\'optimisation du programme avec une vision claire sur la « vue d\'ensemble ». Nos ingénieurs expérimentés ont une capacité étonnante à « voir » les améliorations rapidement, efficacement et à fournir les meilleures solutions en temps opportun et de manière professionnelle. De la gestion des pinces à profil bas OK-VISE à l\'optimisation de l\'utilisation des applications de plaques quadrillées Quick-Point, nous avons les professionnels pour vous guider à chaque étape du processus. Laissez-nous réduire vos coûts d\'usinage des métaux, SANS RISQUE ! Nous ne recevons de paiement que lorsque vous ÉCONOMISEZ DE L\'ARGENT, alors qu\'avez-vous à perdre ? S\'il vous plaît contactez-nous pour obtenir un devis sans engagement sur</font><br></p>', '2023-07-10 00:51:07', '2023-07-10 01:18:49'),
(10, 'App\\Models\\Service', '6475886833b2d-srvs-82683343231452381', 'en', 'title', 'Components Manufacturing Optimization', '2023-07-10 01:16:55', '2023-07-10 01:16:55'),
(11, 'App\\Models\\Service', '6475886833b2d-srvs-82683343231452381', 'en', 'short_description', 'Are your operations costing too much? Encountering consistent problems with bottlenecks, capacity, or quality issues? Do you need assistance with your continuous improvement mandate? Machine Tools Solutions Ltd. can effectively assist you', '2023-07-10 01:16:55', '2023-07-10 01:16:55'),
(12, 'App\\Models\\Service', '6475886833b2d-srvs-82683343231452381', 'en', 'description', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\"><span style=\"font-family: Verdana;\">With proper and thorough consultation with our work-holding equipments expert, we can cut your manufacturing costs! Processing capabilities include cell/fixture/gage design in addition to program optimization with clear vision on the “Big Picture”. Our experienced engineers have an uncanny ability to “see” improvement quickly, efficiently and provide the best solutions in a timely and professional manner. From managing OK-VISE low profile clamps to maximizing the utilization of Quick-Point grid plates applications, we have the professionals to guide you every step of the way. Let us cut your costs on metal working operations, NO RISK! We only receive payment upon your SAVING MONEY, so what do you have to lose? Please CONTACT us to get a no obligation quote on</span><br></p>', '2023-07-10 01:16:55', '2023-07-10 01:16:55'),
(13, 'App\\Models\\Service', '64758824d906f-srvs-80874774476558913', 'en', 'title', 'Re-Certification', '2023-07-10 01:17:05', '2023-07-10 01:17:05'),
(14, 'App\\Models\\Service', '64758824d906f-srvs-80874774476558913', 'en', 'short_description', 'Machine Tool Solutions Ltd. performs re-certification services of permanent magnetic lifters and conducts tests under controlled conditions.', '2023-07-10 01:17:05', '2023-07-10 01:17:05'),
(15, 'App\\Models\\Service', '64758824d906f-srvs-80874774476558913', 'en', 'description', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\"><span style=\"font-family: Verdana;\">Machine Tool Solutions Ltd. performs re-certification services of permanent magnetic lifters and conducts tests under controlled conditions.</span></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\"><span style=\"font-family: Verdana;\">As per O.H.S.A and Regulations for Industrial Establishments R.R.O.1990, Section #51, (R-28), A lifting device shall be thoroughly examined by a competent person to determine its capability of handling the maximum load as rated at least once a year and a permanent record shall be kept, signed by person doing the examination.</span></p>', '2023-07-10 01:17:05', '2023-07-10 01:17:05'),
(16, 'App\\Models\\Service', '647587e2cc9ab-srvs-42720409888247634', 'en', 'title', 'REPAIR AND REFURBISH', '2023-07-10 01:17:09', '2023-07-10 01:17:09'),
(17, 'App\\Models\\Service', '647587e2cc9ab-srvs-42720409888247634', 'en', 'short_description', 'Machine Tool Solutions Ltd. repairs and refurbishes magnetic chucks, lifters, and control units', '2023-07-10 01:17:09', '2023-07-10 01:17:09'),
(18, 'App\\Models\\Service', '647587e2cc9ab-srvs-42720409888247634', 'en', 'description', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\"><span style=\"font-family: Verdana;\">Machine Tool Solutions Ltd. repairs and refurbishes magnetic chucks, lifters, and control units, including:</span></p><ul style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 20px; padding: 0px; direction: ltr; line-height: 1.6; list-style-position: outside; font-family: Lato, helvetica, arial, sans-serif;\"><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><span style=\"font-family: Verdana;\">Magnetic lifters with internal rotating shaft</span></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><span style=\"font-family: Verdana;\">Electro-permanent magnetic chucks for milling, grinding &amp; EDM</span></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><span style=\"font-family: Verdana;\">Control units for magnetic chucks</span></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><span style=\"font-family: Verdana;\">Electro-permanent magnetic lifters remote controlled/wired</span></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><span style=\"font-family: Verdana;\">Other magnetic products</span></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><span style=\"font-family: Verdana;\">Any manufacturer or brand name magnetic products</span></li></ul>', '2023-07-10 01:17:09', '2023-07-10 01:17:09'),
(19, 'App\\Models\\Service', '64758824d906f-srvs-80874774476558913', 'fr', 'title', 'Re-Certification', '2023-07-10 01:20:07', '2023-07-10 01:20:07'),
(20, 'App\\Models\\Service', '64758824d906f-srvs-80874774476558913', 'fr', 'short_description', 'Machine Tool Solutions Ltd. effectue des services de recertification de poussoirs magnétiques permanents et effectue des tests dans des conditions contrôlées.', '2023-07-10 01:20:07', '2023-07-10 01:20:07'),
(21, 'App\\Models\\Service', '64758824d906f-srvs-80874774476558913', 'fr', 'description', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Machine Tool Solutions Ltd. effectue des services de recertification de poussoirs magnétiques permanents et effectue des tests dans des conditions contrôlées.</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Conformément à la O.H.S.A et au Règlement pour les établissements industriels R.R.O.1990, Section #51, (R-28), Un appareil de levage doit être soigneusement examiné par une personne compétente pour déterminer sa capacité à supporter la charge maximale telle qu\'évaluée au moins une fois par an et un un dossier permanent doit être conservé, signé par la personne qui fait l\'examen.</font></p>', '2023-07-10 01:20:07', '2023-07-10 01:20:07'),
(22, 'App\\Models\\Service', '647587e2cc9ab-srvs-42720409888247634', 'fr', 'title', 'RÉPARATION ET REMISE À NEUF', '2023-07-10 01:21:34', '2023-07-10 01:21:34'),
(23, 'App\\Models\\Service', '647587e2cc9ab-srvs-42720409888247634', 'fr', 'short_description', 'Machine Tool Solutions Ltd. répare et remet à neuf les mandrins magnétiques, les poussoirs et les unités de commande', '2023-07-10 01:21:34', '2023-07-10 01:21:34'),
(24, 'App\\Models\\Service', '647587e2cc9ab-srvs-42720409888247634', 'fr', 'description', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Machine Tool Solutions Ltd. répare et remet à neuf des mandrins magnétiques, des poussoirs et des unités de commande, notamment :</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\"><br></font></p><ul><li style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Poussoirs magnétiques avec arbre rotatif interne</font></li><li style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Mandrins magnétiques électro-permanents pour le fraisage, le meulage et l\'EDM</font></li><li style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Unités de commande pour mandrins magnétiques</font></li><li style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Élévateurs magnétiques électro-permanents télécommandés/filaires</font></li><li style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Autres produits magnétiques</font></li><li style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Verdana\">Tous les produits magnétiques du fabricant ou de la marque</font></li></ul>', '2023-07-10 01:21:34', '2023-07-10 01:21:34'),
(25, 'App\\Models\\News', '1', 'fr', 'title', 'Un système de serrage automatisable avec des temps de configuration rapides.', '2023-07-10 01:29:40', '2023-07-10 01:32:48'),
(26, 'App\\Models\\News', '1', 'fr', 'short_description', 'Ce système utilise un cylindre statique qui peut être monté sur le banc de votre machine. Le cylindre statique', '2023-07-10 01:29:40', '2023-07-10 01:32:48'),
(27, 'App\\Models\\News', '1', 'fr', 'description', '<p class=\"newsDetails__container--description\" style=\"\"><font face=\"Jost, sans-serif\"><span style=\"font-size: 19.2px;\">Ce système utilise un cylindre statique qui peut être monté sur le banc de votre machine. Le cylindre statique lui-même est extrêmement bas, un avantage clé de cette conception compacte est la capacité de garder le cylindre installé sur le banc de la machine tout en usinant sur d\'autres montages. Cela réduit le besoin de plusieurs temps de configuration pour différentes opérations et vous permet d\'avoir un certain nombre d\'options de serrage différentes installées sur un seul banc de machine.</span></font></p><p class=\"newsDetails__container--description\" style=\"\"><font face=\"Jost, sans-serif\"><span style=\"font-size: 19.2px;\">Une fois que le cylindre statique est requis, vous disposez de nombreuses options de serrage disponibles à partir d\'un mandrin à trois mors, de mandrins à pince ou même de mandrins expansibles. En fonction de la taille de votre machine, nous pouvons fournir des vérins pour actionner des mandrins de 6\" (165 mm), 8\" (210 mm) ou 10\" (254 mm).</span></font></p><p class=\"newsDetails__container--description\" style=\"\"><font face=\"Jost, sans-serif\"><span style=\"font-size: 19.2px;\"><br></span></font></p><p class=\"newsDetails__container--description\" style=\"\"><font face=\"Jost, sans-serif\"><span style=\"font-size: 19.2px;\">Le cylindre statique YS1415K a une hauteur de seulement 77,5 mm et peut être facilement monté sur des fraiseuses et perceuses. Cette faible hauteur vous permet de monter des porte-pièces ou des pièces plus grandes et de ne pas trop interférer avec la hauteur Z globale. La série de vérins statiques de 10 pouces peut fournir une force de traction allant jusqu\'à 20,8 KN avec un actionnement pneumatique ou une force de traction de 51,9 kN avec un actionnement hydraulique à basse pression (1,5 MPa) avec une course de piston allant jusqu\'à 20 mm. La capacité des vérins vous permet de monter une grande variété de « systèmes de serrage rotatifs de haute précision » sur un appareil fixe.</span></font></p><p class=\"newsDetails__container--description\" style=\"\"><font face=\"Jost, sans-serif\"><span style=\"font-size: 19.2px;\"><br></span></font></p><p class=\"newsDetails__container--description\" style=\"\"><font face=\"Jost, sans-serif\"><span style=\"font-size: 19.2px;\"><br></span></font></p><p class=\"newsDetails__container--description\" style=\"\"><font face=\"Jost, sans-serif\"><span style=\"font-size: 19.2px;\">Plusieurs options de serrage</span></font></p><p class=\"newsDetails__container--description\" style=\"\"><font face=\"Jost, sans-serif\"><span style=\"font-size: 19.2px;\">Le système peut utiliser l\'équipement Kitagawa ou tout système de serrage électrique tiers nécessitant un actionnement par traction ou poussée et le vérin peut être actionné pneumatiquement ou hydrauliquement en fonction du serrage. Vous pouvez commander un simple capuchon de protection à monter sur votre cylindre statique pour protéger le mécanisme lorsqu\'il n\'est pas utilisé.</span></font></p>', '2023-07-10 01:29:40', '2023-07-10 01:32:48'),
(28, 'App\\Models\\News', '1', 'en', 'title', 'An automatable workholding system with fast set up times.', '2023-07-10 01:29:59', '2023-07-10 01:29:59'),
(29, 'App\\Models\\News', '1', 'en', 'short_description', 'This system utilizes a static cylinder that can be mounted onto your machine bed. The static cylinder', '2023-07-10 01:29:59', '2023-07-10 01:29:59'),
(30, 'App\\Models\\News', '1', 'en', 'description', '<p class=\"newsDetails__container--description\" style=\"font-size: 1.2rem; font-family: Jost, sans-serif;\">This system utilizes a static cylinder that can be mounted onto your machine bed. The static cylinder itself is extremely low-profile, a key benefit of this compact design is the capability of keeping the cylinder installed on the machine bed whilst machining on other fixtures. This reduces the requirement of multiple set up times for different operations, and allows you to have a number of different Workholding options installed on a single machine bed.<br>Once the static cylinder is required you have many workholding options available from a three jaw power chuck, collet chucks or even expanding mandrels. Depending on your machine size we can provide cylinders to actuate 6\" (165mm), 8\" (210mm), or 10\" (254mm) chuck sizes.<br><br>The YS1415K static cylinder has a height of just 77.5mm and can be easily mounted to milling and drilling machines. This low height allows you to mount larger Workholding or workpieces and not interfere too much with the overall Z height. The 10” static cylinder series can deliver up to 20.8KN pull force with pneumatic actuation or 51.9kN pull force with low pressure hydraulic actuation (1.5MPa) with up to 20mm of piston stroke. The cylinders capability allows you to mount a huge variety of “high accuracy rotary workholding systems” to a stationary fixture.</p><div class=\"newsDetails__container--images\" style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 10px; max-width: 100%; overflow: hidden; margin: 48px auto; font-family: Jost, sans-serif;\"><img src=\"http://127.0.0.1:8000/assets/img/Category/A1.png\" alt=\"\" class=\"img-fluid\" style=\"width: 251.2px;\"><img src=\"http://127.0.0.1:8000/assets/img/Category/A1.png\" alt=\"\" class=\"img-fluid\" style=\"width: 251.2px;\"><img src=\"http://127.0.0.1:8000/assets/img/Category/A1.png\" alt=\"\" class=\"img-fluid\" style=\"width: 251.2px;\"><img src=\"http://127.0.0.1:8000/assets/img/Category/A1.png\" alt=\"\" class=\"img-fluid\" style=\"width: 251.2px;\"><img src=\"http://127.0.0.1:8000/assets/img/Category/A1.png\" alt=\"\" class=\"img-fluid\" style=\"width: 251.2px;\"></div><h5 class=\"newsDetails__container--subtitle\" style=\"font-size: 1.5rem; font-family: Jost, sans-serif;\"><b>Multiple Workholding options</b></h5><p class=\"newsDetails__container--subdescription\" style=\"font-size: 1.2rem; font-family: Jost, sans-serif;\">The system can utilise Kitagawa equipment or any third party power workholding systems requiring a pull or push actuation and the cylinder can be operated pneumatically or hydraulically depending on the workholding. You can order a simple protective cap to fit to your static cylinder to protect the mechanism when it is not being used.</p>', '2023-07-10 01:29:59', '2023-07-10 01:29:59'),
(31, 'App\\Models\\News', '3', 'en', 'title', 'ECO-COMPACT 20 AUTOMATION SYSTEM', '2023-07-10 01:30:22', '2023-07-10 01:30:22'),
(32, 'App\\Models\\News', '3', 'en', 'short_description', 'Eco-Compact 20 workpiece storage and machine tool automation\r\nThe best automation solution is worthless without the best clamping technology!', '2023-07-10 01:30:22', '2023-07-10 01:30:22'),
(33, 'App\\Models\\News', '3', 'en', 'description', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\">Eco-Compact 20 workpiece storage and machine tool automation<br>The best automation solution is worthless without the best clamping technology!</p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\">With modern and practical clamping solutions, workpieces are manufactured efficiently and reliably through automation. The unique patented form-closure technology of the Makro-Grip centering vise and the robust and highly precise Quick-Point zero-point clamping system make LANG automation systems to the perfect automation solution from one source!</p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\">Our automation devices are:<br>Makro-Grip® automation vice NEW!<br>Makro-Grip® multiple automation clamping vice 77<br>Tri-Top 3-face tombston<br>Automation support pallets (suited for own fixtures, clamping devices or workpieces)</p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\">Our automation clamping devices unite the following characteristics:<br>Recessed grip for handling system<br>Quick-Point clamping studs for zero-point clamping<br>Coloured indicators for bilaterally correct insertion</p>', '2023-07-10 01:30:22', '2023-07-10 01:30:22'),
(34, 'App\\Models\\News', '3', 'fr', 'title', 'SYSTÈME D\'AUTOMATISATION ECO-COMPACT 20', '2023-07-10 01:33:59', '2023-07-10 01:33:59'),
(35, 'App\\Models\\News', '3', 'fr', 'short_description', 'Stockage de pièces Eco-Compact 20 et automatisation de machines-outils\r\nLa meilleure solution d\'automatisation ne vaut rien sans la meilleure technologie de serrage !', '2023-07-10 01:33:59', '2023-07-10 01:33:59'),
(36, 'App\\Models\\News', '3', 'fr', 'description', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Stockage de pièces Eco-Compact 20 et automatisation de machines-outils</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">La meilleure solution d\'automatisation ne vaut rien sans la meilleure technologie de serrage !</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\"><br></font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Grâce à des solutions de serrage modernes et pratiques, les pièces sont fabriquées de manière efficace et fiable grâce à l\'automatisation. La technologie brevetée unique de fermeture de forme de l\'étau de centrage Makro-Grip et le système de serrage à point zéro Quick-Point robuste et très précis font des systèmes d\'automatisation LANG la solution d\'automatisation parfaite à partir d\'une seule source !</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\"><br></font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Nos appareils d\'automatisation sont :</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Etau d\'automatisation Makro-Grip® NOUVEAU !</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Étau de serrage à automatisation multiple Makro-Grip® 77</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Tri-Top tombston 3 faces</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Palettes de support d\'automatisation (adaptées à vos propres montages, dispositifs de serrage ou pièces à usiner)</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\"><br></font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Nos dispositifs de serrage automatisés réunissent les caractéristiques suivantes :</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Poignée encastrée pour système de manutention</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Goujons de serrage Quick-Point pour un serrage au point zéro</font></p><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><font face=\"Lato, helvetica, arial, sans-serif\">Indicateurs colorés pour une insertion bilatéralement correcte</font></p>', '2023-07-10 01:33:59', '2023-07-10 01:33:59'),
(37, 'App\\Models\\Product', '64a3c1d7b217d-prod-37137022000517371', 'en', 'name', 'ELECTRO-PERMANENT magnetic lifting or handling', '2023-07-10 01:52:15', '2023-07-10 01:52:15'),
(38, 'App\\Models\\Product', '64a3c1d7b217d-prod-37137022000517371', 'en', 'key_features', '<p><span style=\"font-family: Lato, helvetica, arial, sans-serif;\">Unlike the electromagnetic field, this new system uses electric power only during the magnetization and demagnetization phases. Each of them takes only a few seconds. During the operation phase, when the magnetic force is active, the product is permanently magnetized so that nothing can alter its state except for a demagnetization electrical impulse. For example: if an electro-permanent product is magnetized, then voltage is disconnected, cables unplugged, and the piece is left to hang magnetically for a year, it will not fall. In order to demagnetize it, simply connect the voltage again and send a demagnetization impulse. It goes without saying that no electric power is wasted and, moreover, you are absolutely safe against voltage drops.</span><br></p>', '2023-07-10 01:52:15', '2023-07-10 01:52:15'),
(39, 'App\\Models\\Product', '64a3c1d7b217d-prod-37137022000517371', 'en', 'further_information', '<p><br></p>', '2023-07-10 01:52:15', '2023-07-10 01:52:15'),
(40, 'App\\Models\\Product', '647d8195cc6a3-prod-81909702939051446', 'en', 'name', 'Makro-Grip 5 axis vice 77', '2023-07-10 01:52:22', '2023-07-10 02:08:16'),
(41, 'App\\Models\\Product', '647d8195cc6a3-prod-81909702939051446', 'en', 'key_features', '<p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; line-height: 1.6; text-rendering: optimizelegibility;\"><span style=\"font-family: Helvetica;\">The popular 5-axis vise with a clamping range of 0 - 120 mm and a jaw width of 77 mm is the ideal machine vise for 5-axis machining of unmachined parts. It is used both in manual milling and in automated production with RoboTrex. Workpieces are clamped by form-fit in the clamping jaws of the centering vise with a clamping depth of just 3 mm. Due to the centric clamping and the slim design, clamped workpieces are ideally accessible from all sides. On the side of the base body, it has an automation interface to be gripped directly by the robot\'s gripper.</span><br></p>', '2023-07-10 01:52:22', '2023-09-07 00:08:24'),
(42, 'App\\Models\\Product', '647d8195cc6a3-prod-81909702939051446', 'en', 'further_information', '<ul class=\"mg5ul\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 20px; padding: 0px; direction: ltr; line-height: 1.6; list-style-position: outside; font-family: Lato, helvetica, arial, sans-serif;\"><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><p class=\"mg5\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><strong style=\"font-weight: bold; line-height: inherit;\">Grid system:</strong>&nbsp;Pitch of the zero-point system</p><p class=\"mg5_r\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><img src=\"https://machinetoolsolutions.ca/wp-content/uploads/2016/01/av1.jpg\" alt=\"Pitch of the zero-point system\" style=\"border: 0px; max-width: 100%; height: auto; display: inline-block;\"></p></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><p class=\"mg5\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><strong style=\"font-weight: bold; line-height: inherit;\">Clamping stud size:</strong>&nbsp;Diameter of the clamping studs</p><p class=\"mg5_r\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><img src=\"https://machinetoolsolutions.ca/wp-content/uploads/2016/03/av2.jpg\" alt=\"Diameter of the clamping studs\" style=\"border: 0px; max-width: 100%; height: auto; display: inline-block;\"></p></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><p class=\"mg5\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><strong style=\"font-weight: bold; line-height: inherit;\">Actuation Torque Item</strong>&nbsp;No. 45720</p><p class=\"mg5_r\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><img src=\"https://machinetoolsolutions.ca/wp-content/uploads/2016/01/av3_a.jpg\" alt=\"Actuation Torque Item No. 45720\" style=\"border: 0px; max-width: 100%; height: auto; display: inline-block;\"></p></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><p class=\"mg5\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><strong style=\"font-weight: bold; line-height: inherit;\">Centring accuracy:</strong>&nbsp;Centring tolerances of vices</p><p class=\"mg5_r\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><img src=\"https://machinetoolsolutions.ca/wp-content/uploads/2016/01/av4.jpg\" alt=\"Centring tolerances of vices\" style=\"border: 0px; max-width: 100%; height: auto; display: inline-block;\"></p></li><li style=\"margin: 0px; padding: 0px; direction: ltr;\"><p class=\"mg5\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><strong style=\"font-weight: bold; line-height: inherit;\">Clamping force:</strong>&nbsp;Clamping force at max. torque</p><p class=\"mg5_r\" style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-size: 1em; line-height: 1.6; text-rendering: optimizelegibility;\"><img src=\"https://machinetoolsolutions.ca/wp-content/uploads/2016/01/av5_a.jpg\" alt=\"Clamping force at max. torque\" style=\"border: 0px; max-width: 100%; height: auto; display: inline-block;\"></p></li></ul><p style=\"margin-right: 0px; margin-bottom: 1.25em; margin-left: 0px; padding: 0px; direction: ltr; font-family: Lato, helvetica, arial, sans-serif; line-height: 1.6; text-rendering: optimizelegibility;\"><img src=\"https://machinetoolsolutions.ca/wp-content/uploads/2016/10/Makro-Grip-77-Drawings.jpg\" alt=\"\" width=\"70%\" height=\"auto\" style=\"border: 0px; max-width: 100%; height: auto; display: inline-block;\"></p>', '2023-07-10 01:52:22', '2023-07-10 01:52:22'),
