(144, 'App\\Models\\Product', '6501a0d926df3-prod-40840975459418546', 'en', 'name', 'Makro•Grip 77, HAUBEX 5-Axis Vise', '2023-09-13 18:45:29', '2023-09-13 18:45:29'),
(145, 'App\\Models\\Product', '6501a0d926df3-prod-40840975459418546', 'en', 'key_features', '<p style=\"margin-right: 0px; margin-bottom: 13.8889px; margin-left: 0px; padding: 0px; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-stretch: inherit; line-height: 24px; font-optical-sizing: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; vertical-align: baseline;\">HAUBEX uses a modified version of the Makro•Grip® as the workholding device. The slim design of the 5-Axis Vice and the narrow jaw width of 46 mm ensure ideal accessibility in 5-sided machining of blanks. The maximum workpiece size of approx. 80 × 75 × 70 mm is given by the height and diameter of the workholding hood. Examples of possible dimensions and a formula for their calculation can be found on the data sheet in the downloads.</p><p class=\"product__name\" style=\"margin-right: 0px; margin-bottom: 13.8889px; margin-left: 0px; padding: 0px; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-stretch: inherit; line-height: 24px; font-optical-sizing: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; vertical-align: baseline;\"><span style=\"border-style: initial; border-color: initial; border-image: initial; font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-optical-sizing: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit;\"><b>Jaw width (mm):</b></span>&nbsp;46 mm</p><p class=\"product__name\" style=\"margin-right: 0px; margin-bottom: 13.8889px; margin-left: 0px; padding: 0px; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-stretch: inherit; line-height: 24px; font-optical-sizing: inherit; font-kerning: inherit; font-feat