(531, 'App\\Models\\Product', '6528369692e97-prod-55562946982379098', 'en', 'name', 'Makro•Grip® Ultra 125, Center Jaw', '2023-10-13 01:10:30', '2023-10-13 01:10:30'),
(532, 'App\\Models\\Product', '6528369692e97-prod-55562946982379098', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The center jaw with serrations on both sides enables multiple clamping in the Makro•Grip®® Ultra system. It is mounted directly on the two middle base bodies of the system and used in combination with the Makro•Grip® clamping jaws with 5 mm clamping depth (item no. 81485). Thanks to special centering plates, components with a slight variance in length can be clamped in a compensating manner.</p>', '2023-10-13 01:10:30', '2023-10-13 01:10:30'),
