(987, 'App\\Models\\Product', '652c1f68e78e6-prod-64913459613227478', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The set – comprising threaded spindle with centre piece – is used in all LANG vices with the same system body length. The spindle is provided with a low-wear TIN coating and thus ensures maximum durability. The spindle M 16 x 1.5 mm can be operated with an internal hexagon (SW 5) or an external hexagon (SW 12).</p>', '2023-10-16 00:20:40', '2023-10-16 00:20:40'),
(988, 'App\\Models\\Product', '652c1f8e04036-prod-72565801179591459', 'en', 'name', 'Makro•Grip® 77, Set Spindle + Center Piece', '2023-10-16 00:21:18', '2023-10-16 00:21:18'),
(989, 'App\\Models\\Product', '652c1f8e04036-prod-72565801179591459', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The set – comprising threaded spindle with centre piece – is used in all LANG vices with the same system body length. The spindle is provided with a low-wear TIN coating and thus ensures maximum durability. The spindle M 16 x 1.5 mm can be operated with an internal hexagon (SW 5) or an external hexagon (SW 12).</p>', '2023-10-16 00:21:18', '2023-10-16 00:21:18'),
(1005, 'App\\Models\\Product', '652c23f0da311-prod-66329652040528108', 'en', 'name', 'Quick•Point® 96, Modular Plate 2-fold', '2023-10-16 00:40:00', '2023-10-16 00:40:00'),
(1006, 'App\\Models\\Product', '652c23f0da311-prod-66329652040528108', 'en', 'key_features', '<p></p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: \" encode=\"\" sans=\"\" compressed\",=\"\" sans-serif;=\"\" font-size:=\"\" 20px;=\"\" font-style:=\"\" normal;=\"\" font-variant-ligatures:=\"\" font-variant-caps:=\"\" font-weight:=\"\" 400;=\"\" letter-spacing:=\"\" 0.8px;=\"\" orphans:=\"\" 2;=\"\" text-align:=\"\" left;=\"\" text-indent:=\"\" 0px;=\"\" text-transform:=\"\" none;=\"\" widows:=\"\" word-spacing:=\"\" -webkit-text-stroke-width:=\"\" white-space:=\"\" background-color:=\"\" rgb(247,=\"\" 247,=\"\" 248);=\"\" text-decoration-thickness:=\"\" initial;=\"\" text-decoration-style:=\"\" text-decoration-color:=\"\" initial;\"=\"\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div><p></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The new expandable Quick•Point® modular plates are characterized by even more simple, faster and user-friendly handling.With just one tightening screw, several module plates can be actuated together. A total of two 2-fold modular plates and one 1-fold modular plate can be connected in series (resulting in a length of 960 mm in the y-direction). This makes it easy to create a cross-plate zero-point grid across the entire machine table that works in both the x- and y-directions. The Quick•Point® modular plates are available without predefined mounting holes, which allows completely individual adaptation to the conditions of the machine table. LANG offers the insertion of the necessary mounting holes as a service, but this can also be done by the customer.</p>', '2023-10-16 00:40:00', '2024-02-01 03:06:11'),
(1007, 'App\\Models\\Product', '652c23f0da311-prod-66329652040528108', 'en', 'further_information', '<p><br></p>', '2023-10-16 00:40:00', '2023-10-16 00:40:00'),
(1014, 'App\\Models\\Product', '652c27141a264-prod-32446495790435154', 'en', 'name', 'Quick•Point® 96, Modular Plate 1-fold', '2023-10-16 00:53:24', '2023-10-16 00:53:24');
INSERT INTO `translations` (`id`, `translatable_type`, `translatable_id`, `language_code`, `field`, `value`, `created_at`, `updated_at`) VALUES
(1015, 'App\\Models\\Product', '652c27141a264-prod-32446495790435154', 'en', 'key_features', '<p></p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: \" encode=\"\" sans=\"\" compressed\",=\"\" sans-serif;=\"\" font-size:=\"\" 20px;=\"\" font-style:=\"\" normal;=\"\" font-variant-ligatures:=\"\" font-variant-caps:=\"\" font-weight:=\"\" 400;=\"\" letter-spacing:=\"\" 0.8px;=\"\" orphans:=\"\" 2;=\"\" text-align:=\"\" left;=\"\" text-indent:=\"\" 0px;=\"\" text-transform:=\"\" none;=\"\" widows:=\"\" word-spacing:=\"\" -webkit-text-stroke-width:=\"\" white-space:=\"\" background-color:=\"\" rgb(247,=\"\" 247,=\"\" 248);=\"\" text-decoration-thickness:=\"\" initial;=\"\" text-decoration-style:=\"\" text-decoration-color:=\"\" initial;\"=\"\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div><p></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The new expandable Quick•Point® modular plates are characterized by even more simple, faster and user-friendly handling. The 1-fold modular plate is usually added to a 2-fold modular plate and connected to it via a connecting set. The patented clamping mechanism allows the connected modular plates to be actuated with just one tightening screw and clamping devices can be clamped in a cross-plate zero-point grid. The Quick•Point® modular plates are available without predefined mounting holes and can therefore be individually adapted to the conditions of the machine table. LANG offers the insertion of the necessary mounting holes as a service, but this can also be done by the customer.<br style=\"box-sizing: inherit;\"></p>', '2023-10-16 00:53:24', '2024-02-01 03:06:38'),
(1016, 'App\\Models\\Product', '652c27141a264-prod-32446495790435154', 'en', 'further_information', '<p><br></p>', '2023-10-16 00:53:24', '2023-10-16 00:53:24'),
(1026, 'App\\Models\\Product', '652c29df11e19-prod-26152075087754997', 'en', 'name', 'Profilo 77, Center Jaw + Spindle', '2023-10-16 01:05:19', '2023-10-16 01:05:19'),
(1027, 'App\\Models\\Product', '652c29df11e19-prod-26152075087754997', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">If required, the Profilo vise can be converted into a multiple clamping vise. During the conversion, which can be carried out in a few moments, only the set of spindle + center piece from the vise has to be replaced by the center base jaw + spindle. For (multiple) workpiece clamping, the same top jaw as for the base jaws is mounted on the center base jaw.</p>', '2023-10-16 01:05:19', '2023-10-16 01:05:19'),
(1028, 'App\\Models\\Product', '652c29df11e19-prod-26152075087754997', 'en', 'further_information', '<p><br></p>', '2023-10-16 01:05:19', '2023-10-16 01:05:19'),
(1035, 'App\\Models\\Category', '652c2de365aba-ctgr-71698838680998823', 'en', 'title', 'Spare Jaws vario', '2023-10-16 01:22:27', '2023-10-16 01:22:27'),
(1036, 'App\\Models\\Category', '652c2e1024a72-ctgr-25355305303292223', 'en', 'title', 'Centering Vises vario', '2023-10-16 01:23:12', '2023-10-16 01:23:12'),
(1037, 'App\\Models\\Category', '652c2e88960ea-ctgr-35054896800434700', 'en', 'title', 'Old version vario', '2023-10-16 01:25:12', '2023-10-16 01:25:12'),
(1086, 'App\\Models\\Product', '652cca561c3b2-prod-59825179796049972', 'en', 'name', 'Vario•Tec 125, Centering Vise', '2023-10-16 12:29:58', '2023-10-16 12:29:58'),
(1087, 'App\\Models\\Product', '652cca561c3b2-prod-59825179796049972', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The Vario•Tec centering vise offers a convenient and variable support and positioning system for (semi-) finished workpieces. The Vario•Tec clamping jaws contain movable pins with high positioning accuracy, which are blown out row by row with compressed air and can be pushed back individually when not in use, thus generating specific clamping angles. This facilitates the easy and repeatable setting of the desired configuration and eliminates the need for additional workpiece end stops and parallels.</p>', '2023-10-16 12:29:58', '2023-10-16 12:29:58'),
(1088, 'App\\Models\\Product', '652cca561c3b2-prod-59825179796049972', 'en', 'further_information', '<p><br></p>', '2023-10-16 12:29:58', '2023-10-16 12:29:58'),
(1089, 'App\\Models\\Product', '652cccbda04d4-prod-89404600371994588', 'en', 'name', 'Vario•Tec 125, Centering Vise', '2023-10-16 12:40:13', '2023-10-16 12:40:13'),
(1090, 'App\\Models\\Product', '652cccbda04d4-prod-89404600371994588', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The Vario•Tec centering vise offers a convenient and variable support and positioning system for (semi-) finished workpieces. The Vario•Tec clamping jaws contain movable pins with high positioning accuracy, which are blown out row by row with compressed air and can be pushed back individually when not in use, thus generating specific clamping angles. This facilitates the easy and repeatable setting of the desired configuration and eliminates the need for additional workpiece end stops and parallels.</p>', '2023-10-16 12:40:13', '2023-10-16 12:40:13'),
