(1172, 'App\\Models\\Product', '652d158d58a0a-prod-34382626459872965', 'en', 'name', 'Quick•Point® 96, Riser round, ø 246 / 176 mm, height 60 mm', '2023-10-16 10:50:53', '2023-10-16 10:50:53'),
(1173, 'App\\Models\\Product', '652d158d58a0a-prod-34382626459872965', 'en', 'key_features', '<p></p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: \" encode=\"\" sans=\"\" compressed\",=\"\" sans-serif;=\"\" font-size:=\"\" 20px;=\"\" font-style:=\"\" normal;=\"\" font-variant-ligatures:=\"\" font-variant-caps:=\"\" font-weight:=\"\" 400;=\"\" letter-spacing:=\"\" 0.8px;=\"\" orphans:=\"\" 2;=\"\" text-align:=\"\" left;=\"\" text-indent:=\"\" 0px;=\"\" text-transform:=\"\" none;=\"\" widows:=\"\" word-spacing:=\"\" -webkit-text-stroke-width:=\"\" white-space:=\"\" background-color:=\"\" rgb(247,=\"\" 247,=\"\" 248);=\"\" text-decoration-thickness:=\"\" initial;=\"\" text-decoration-style:=\"\" text-decoration-color:=\"\" initial;\"=\"\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div><p></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The aluminum riser improves accessibility in 5-sided machining. It can either be mounted directly and firmly on the machine table or be set up on a zero point plate. The round base is designed for the Quick•Point® 96 system and can be equipped with the two zero point plates 45800 and 45480. In addition to this variant with a total height of 60 mm, the round riser is also available with a height of 100 mm.</p>', '2023-10-16 10:50:53', '2024-02-01 03:14:58'),
