(1723, 'App\\Models\\Product', '6577e28dbbe67-prod-26666525550149475', 'en', 'key_features', '<p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248);\"><span style=\"font-weight: bolder; background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\">Pins:</span><span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">&nbsp;76</span><br></p><p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248);\"><span style=\"font-weight: bolder;\">Pin Ø:</span>&nbsp;<span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">3.5 mm</span><span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">&nbsp;</span></p><p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248);\"><span style=\"font-weight: bolder;\">Pin Stroke:</span>&nbsp;<span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">20 mm</span><span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">&nbsp;</span></p><p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248);\"><span style=\"font-weight: bolder;\">Pin Field Dimension:</span>&nbsp;<span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">35.3 mm x 31 mm</span></p><p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248);\"><span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"><span style=\"font-weight: bolder;\">Total Dimension:</span></span><span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">&nbsp;56 mm x 46 mm</span></p><p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248);\"><span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"><span style=\"font-weight: bolder;\">Total Height:</span></span><span style=\"background-color: var(--bs-modal-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">&nbsp;132 mm</span></p>', '2023-12-12 11:33:17', '2024-03-27 22:32:18'),
(1724, 'App\\Models\\Product', '6577e28dbbe67-prod-26666525550149475', 'en', 'further_information', '<p><br></p>', '2023-12-12 11:33:17', '2023-12-12 11:33:17'),
(1725, 'App\\Models\\Service', '65814427ad649-srvs-60800147603687405', 'en', 'title', 'What is Lorem Ipsum', '2023-12-19 14:20:07', '2023-12-19 14:20:07'),
