(1806, 'App\\Models\\ProductPart', '65a23548481d1-pprt-32062513147014401', 'en', 'name', 'Quick•Point® Rail, Connector', '2024-01-13 14:01:28', '2024-01-13 14:01:28'),
(1807, 'App\\Models\\ProductPart', '65a23548481d1-pprt-32062513147014401', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The connector allows the clamping and extension bars of the Quick-Point® Rail System to be mounted to each other.</p>', '2024-01-13 14:01:28', '2024-01-13 14:01:28'),
(1808, 'App\\Models\\ProductPart', '65a23548481d1-pprt-32062513147014401', 'en', 'further_information', '<p><br></p>', '2024-01-13 14:01:28', '2024-01-13 14:01:28'),
(1809, 'App\\Models\\ProductPart', '65a27bc4bdf63-pprt-25321509990214591', 'en', 'name', 'Makro•Grip® FS, Conversion set', '2024-01-13 19:02:12', '2024-01-13 19:02:12'),
(1810, 'App\\Models\\ProductPart', '65a27bc4bdf63-pprt-25321509990214591', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">With the conversion set, stamping jaws of the new Makro•Grip® FS series can be used on all existing stamping units. The conversion set consists of a fixed and a movable carrier jaw for the stamping jaws. The stamping jaws themselves are not included in the scope of delivery.</p>', '2024-01-13 19:02:12', '2024-01-13 19:02:12'),
(1811, 'App\\Models\\ProductPart', '65a27bc4bdf63-pprt-25321509990214591', 'en', 'further_information', '<p><br></p>', '2024-01-13 19:02:12', '2024-01-13 19:02:12'),
(1812, 'App\\Models\\ProductPart', '65a27caac68a7-pprt-65923309492110809', 'en', 'name', 'Makro•Grip® FS, Set centering device and depth gauge', '2024-01-13 19:06:02', '2024-01-13 19:06:02'),
(1813, 'App\\Models\\ProductPart', '65a27caac68a7-pprt-65923309492110809', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The new accessories for Makro•Grip® stamping units - centering device and depth gauge - are also available as a set. Using this set makes operation of the stamping unit even easier and more effective. The centering device speeds up the exact centering of workpiece blanks up to 205 mm wide, since no prior measurement is required. With the stamping depth gauge / measuring device, the correct stamping pressure or stamping depth can be read off on a dial gauge.</p>', '2024-01-13 19:06:02', '2024-01-13 19:06:02'),
(1814, 'App\\Models\\ProductPart', '65a27caac68a7-pprt-65923309492110809', 'en', 'further_information', '<p><br></p>', '2024-01-13 19:06:02', '2024-01-13 19:06:02'),
(1815, 'App\\Models\\ProductPart', '65a27d914036e-pprt-88991006884961321', 'en', 'name', 'Makro•Grip® FS, Depth gauge', '2024-01-13 19:09:53', '2024-01-13 19:09:53');
INSERT INTO `translations` (`id`, `translatable_type`, `translatable_id`, `language_code`, `field`, `value`, `created_at`, `updated_at`) VALUES
(1816, 'App\\Models\\ProductPart', '65a27d914036e-pprt-88991006884961321', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The stamping depth gauge is available as an accessory for each stamping unit of the Makro•Grip® FS series. The use of this measuring device makes it easier and faster to set correct the stamping pressure. A visual inspection of the workpiece blank and possible re-stamping are no longer necessary. Instead, it is enough to simply increase the pressure until the desired stamping depth is reached. The stamping depth can be easily read off the dial gauge. This method makes the entire stamping process more reliable, as it is based less on experience or feeling and more on exact data.</p>', '2024-01-13 19:09:53', '2024-01-13 19:09:53'),
(1817, 'App\\Models\\ProductPart', '65a27d914036e-pprt-88991006884961321', 'en', 'further_information', '<p><br></p>', '2024-01-13 19:09:53', '2024-01-13 19:09:53'),
(1818, 'App\\Models\\ProductPart', '65a27e30e5d48-pprt-73172092007532664', 'en', 'name', 'Makro•Grip® FS, Set centering device and depth gauge', '2024-01-13 19:12:32', '2024-01-13 19:12:32'),
(1819, 'App\\Models\\ProductPart', '65a27e30e5d48-pprt-73172092007532664', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The new accessories for Makro•Grip® stamping units - centering device and depth gauge - are also available as a set. Using this set makes operation of the stamping unit even easier and more effective. The centering device speeds up the exact centering of workpiece blanks up to 205 mm wide, since no prior measurement is required. With the stamping depth gauge / measuring device, the correct stamping pressure or stamping depth can be read off on a dial gauge.</p>', '2024-01-13 19:12:32', '2024-01-13 19:12:32'),
(1820, 'App\\Models\\ProductPart', '65a27e30e5d48-pprt-73172092007532664', 'en', 'further_information', '<p><br></p>', '2024-01-13 19:12:32', '2024-01-13 19:12:32'),
(1821, 'App\\Models\\ProductPart', '65a27f6bd6138-pprt-59153097833838958', 'en', 'name', 'Makro•Grip® FS, Centering device', '2024-01-13 19:17:47', '2024-01-13 19:17:47'),
(1822, 'App\\Models\\ProductPart', '65a27f6bd6138-pprt-59153097833838958', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The centering device, suitable for all stamping units of the Makro•Grip® FS series, facilitates the exact centering of the workpiece blank in the stamping unit. Users benefit from time savings during setup, greater ease of operation, and reduced susceptibility to errors due to their own fault. With the new centering device, which is available as an accessory, workpiece blanks up to 205 mm wide can be inserted exactly in the center. This eliminates the need to measure the workpiece blank beforehand.</p>', '2024-01-13 19:17:47', '2024-01-13 19:17:47'),
(1823, 'App\\Models\\ProductPart', '65a27f6bd6138-pprt-59153097833838958', 'en', 'further_information', '<p><br></p>', '2024-01-13 19:17:47', '2024-01-13 19:17:47'),
(1824, 'App\\Models\\ProductPart', '65a28012453c8-pprt-68282642222686446', 'en', 'name', 'Makro•Grip® FS, Set centering device and depth gauge', '2024-01-13 19:20:34', '2024-01-13 19:20:34'),
(1825, 'App\\Models\\ProductPart', '65a28012453c8-pprt-68282642222686446', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The new accessories for Makro•Grip® stamping units - centering device and depth gauge - are also available as a set. Using this set makes operation of the stamping unit even easier and more effective. The centering device speeds up the exact centering of workpiece blanks up to 205 mm wide, since no prior measurement is required. With the stamping depth gauge / measuring device, the correct stamping pressure or stamping depth can be read off on a dial gauge.</p>', '2024-01-13 19:20:34', '2024-01-13 19:20:34'),
(1826, 'App\\Models\\ProductPart', '65a28012453c8-pprt-68282642222686446', 'en', 'further_information', '<p><br></p>', '2024-01-13 19:20:34', '2024-01-13 19:20:34'),
(1827, 'App\\Models\\ProductPart', '65a2815ccd1cc-pprt-89150010613384045', 'en', 'name', 'Makro•Grip® FS, Gauging Blocks', '2024-01-13 19:26:04', '2024-01-13 19:26:04'),
(1828, 'App\\Models\\ProductPart', '65a2815ccd1cc-pprt-89150010613384045', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">This new version of the gauging blocks is suitable for the stamping jaws of the Makro•Grip® FS stamping units. The gauging blocks, which are included in the scope of delivery of each stamping unit, are used to measure the wear on the serration of the stamping jaws. Regular checking of the serration helps to ensure consistently high quality in workpiece clamping. If one of the four rows of serration is worn, the stamping jaws of the Makro•Grip® FS series are simply turned three more times.</p>', '2024-01-13 19:26:04', '2024-01-13 19:26:04'),
(1829, 'App\\Models\\ProductPart', '65a2815ccd1cc-pprt-89150010613384045', 'en', 'further_information', '<p><br></p>', '2024-01-13 19:26:04', '2024-01-13 19:26:04'),
(1830, 'App\\Models\\ProductPart', '65a282506e421-pprt-35247242445504526', 'en', 'name', 'Quick•Point®, Quick•Lock Clamping Lever 52 / 96, for Multi Plates', '2024-01-13 19:30:08', '2024-01-27 03:01:46'),
(1831, 'App\\Models\\ProductPart', '65a282506e421-pprt-35247242445504526', 'en', 'key_features', '<p></p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: \" encode=\"\" sans=\"\" compressed\",=\"\" sans-serif;=\"\" font-size:=\"\" 20px;=\"\" font-style:=\"\" normal;=\"\" font-variant-ligatures:=\"\" font-variant-caps:=\"\" font-weight:=\"\" 400;=\"\" letter-spacing:=\"\" 0.8px;=\"\" orphans:=\"\" 2;=\"\" text-align:=\"\" left;=\"\" text-indent:=\"\" 0px;=\"\" text-transform:=\"\" none;=\"\" widows:=\"\" word-spacing:=\"\" -webkit-text-stroke-width:=\"\" white-space:=\"\" background-color:=\"\" rgb(247,=\"\" 247,=\"\" 248);=\"\" text-decoration-thickness:=\"\" initial;=\"\" text-decoration-style:=\"\" text-decoration-color:=\"\" initial;\"=\"\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div><p></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">With this clamping lever, the user conveniently operates the Quick•Lock quick-release fastener mounted on a zero point plate with a 180° closing movement. This clamping lever is used for Quick•Lock quick-release fasteners mounted on multiple grid plates.</p>', '2024-01-13 19:30:08', '2024-01-27 03:01:46'),
