(1889, 'App\\Models\\ProductPart', '65a355d3ee518-pprt-37644576856140097', 'en', 'further_information', '<p><br></p>', '2024-01-14 10:32:35', '2024-01-14 10:32:35'),
(1890, 'App\\Models\\ProductPart', '65a356a85e3ae-pprt-39974442282038948', 'en', 'name', 'Quick•Point® 52, Gauging Pallet', '2024-01-14 10:36:08', '2024-01-14 10:36:08'),
(1891, 'App\\Models\\ProductPart', '65a356a85e3ae-pprt-39974442282038948', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The coordinate-ground gauging pallet enables quick and accurate alignment of Quick-Point® plates. This is particularly recommended for rotating axes and chucks. For concentric alignment of the zero-point plate, the inner diameter of the measuring body is used, while for axial alignment the side surfaces of the measuring body are traversed.</p>', '2024-01-14 10:36:08', '2024-01-14 10:36:08'),
(1892, 'App\\Models\\ProductPart', '65a356a85e3ae-pprt-39974442282038948', 'en', 'further_information', '<p><br></p>', '2024-01-14 10:36:08', '2024-01-14 10:36:08'),
(1893, 'App\\Models\\ProductPart', '65a3585a7b3ae-pprt-16305145719271613', 'en', 'name', 'HAUBEX, Clamping Lever', '2024-01-14 10:43:22', '2024-01-14 10:43:22');
INSERT INTO `translations` (`id`, `translatable_type`, `translatable_id`, `language_code`, `field`, `value`, `created_at`, `updated_at`) VALUES
(1894, 'App\\Models\\ProductPart', '65a3585a7b3ae-pprt-16305145719271613', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">This clamping lever is used to manually operate the Quick•Point® HAUBEX zero-point clamping system when it is used in manual machining without a workholding hood.</p>', '2024-01-14 10:43:22', '2024-01-14 10:43:22'),
(1895, 'App\\Models\\ProductPart', '65a3585a7b3ae-pprt-16305145719271613', 'en', 'further_information', '<p><br></p>', '2024-01-14 10:43:22', '2024-01-14 10:43:22'),
(1896, 'App\\Models\\ProductPart', '65a359253db49-pprt-61496386010842213', 'en', 'name', 'Preci•Point, Clamping Wrench', '2024-01-14 10:46:45', '2024-01-14 10:46:45'),
(1897, 'App\\Models\\ProductPart', '65a359253db49-pprt-61496386010842213', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Handy, sturdy clamping spanner made of steel for operating the clamping nut of the Preci•Point ER 50collet chuck.</p>', '2024-01-14 10:46:45', '2024-01-14 10:46:45'),
(1898, 'App\\Models\\ProductPart', '65a359253db49-pprt-61496386010842213', 'en', 'further_information', '<p><br></p>', '2024-01-14 10:46:45', '2024-01-14 10:46:45'),
(1899, 'App\\Models\\ProductPart', '65a359dd675fe-pprt-53390590724965004', 'en', 'name', 'Preci•Point, Clamping Wrench', '2024-01-14 10:49:49', '2024-01-14 10:49:49'),
(1900, 'App\\Models\\ProductPart', '65a359dd675fe-pprt-53390590724965004', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Handy, sturdy clamping spanner made of steel for operating the clamping nut of the Preci•Point ER 32 collet chuck.</p>', '2024-01-14 10:49:49', '2024-01-14 10:49:49'),
(1901, 'App\\Models\\ProductPart', '65a359dd675fe-pprt-53390590724965004', 'en', 'further_information', '<p><br></p>', '2024-01-14 10:49:49', '2024-01-14 10:49:49'),
(1902, 'App\\Models\\ProductPart', '65a35afe2fafd-pprt-59797981445294285', 'en', 'name', 'Quick•Point® 52, Handle Bar', '2024-01-14 10:54:38', '2024-01-14 10:54:38'),
(1903, 'App\\Models\\ProductPart', '65a35afe2fafd-pprt-59797981445294285', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The easy-to-use handle made of aluminium makes it easier to handle the Quick•Point® products when setting up and dismantling. Just like with the usual LANG clamping devises, the aluminium handle is clamped in the zero-point clamping system with two Quick•Point® clamping studs and is, therefore, particularly suitable for transporting heavier products, such as 5-axis risers or the zero-point automation devises.</p>', '2024-01-14 10:54:38', '2024-01-14 10:54:38'),
(1904, 'App\\Models\\ProductPart', '65a35afe2fafd-pprt-59797981445294285', 'en', 'further_information', '<p><br></p>', '2024-01-14 10:54:38', '2024-01-14 10:54:38'),
(1905, 'App\\Models\\ProductPart', '65a35ba0ce814-pprt-96970708252980421', 'en', 'name', 'Quick•Point® 96, Handle Bar', '2024-01-14 10:57:20', '2024-01-14 10:57:20'),
(1906, 'App\\Models\\ProductPart', '65a35ba0ce814-pprt-96970708252980421', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The easy-to-use handle made of aluminium makes it easier to handle the Quick•Point® products when setting up and dismantling. Just like with the usual LANG clamping devises, the aluminium handle is clamped in the zero-point clamping system with two Quick•Point® clamping studs and is, therefore, particularly suitable for transporting heavier products, such as 5-axis risers or the zero-point automation devises.</p>', '2024-01-14 10:57:20', '2024-01-14 10:57:20'),
(1907, 'App\\Models\\ProductPart', '65a35ba0ce814-pprt-96970708252980421', 'en', 'further_information', '<p><br></p>', '2024-01-14 10:57:20', '2024-01-14 10:57:20'),
