(1947, 'App\\Models\\ProductPart', '65a50749c8834-pprt-77570775797363849', 'en', 'name', 'Makro•Grip®, End-Stop', '2024-01-15 17:22:01', '2024-01-15 17:22:01'),
(1948, 'App\\Models\\ProductPart', '65a50749c8834-pprt-77570775797363849', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The universal end stop for all versions of the Makro•Grip® stamping unit enables the workpiece blank to be inserted into the center of the stamping unit with high repeat accuracy. It is attached to the side via an M 10 thread. Its thorn is provided with a scale. An exact centered positioning of the blank is guaranteed when the value on the scale is exactly half of the workpiece width. (e.g. workpiece width 80 mm = setting value scaling 40).</p>', '2024-01-15 17:22:01', '2024-01-15 17:22:01'),
(1949, 'App\\Models\\ProductPart', '65a50749c8834-pprt-77570775797363849', 'en', 'further_information', '<p><br></p>', '2024-01-15 17:22:01', '2024-01-15 17:22:01'),
(1950, 'App\\Models\\ProductPart', '65a508116f996-pprt-61801578261180605', 'en', 'name', 'RoboTrex, Trolley Entry System', '2024-01-15 17:25:21', '2024-01-15 17:25:21'),
(1951, 'App\\Models\\ProductPart', '65a508116f996-pprt-61801578261180605', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The Entry System is used equally for the RoboTrex 52 and 96 automation systems. It ensures precise positioning of the automation trolleys in the system.</p>', '2024-01-15 17:25:21', '2024-01-15 17:25:21'),
(1952, 'App\\Models\\ProductPart', '65a508116f996-pprt-61801578261180605', 'en', 'further_information', '<p><br></p>', '2024-01-15 17:25:21', '2024-01-15 17:25:21'),
(1953, 'App\\Models\\ProductPart', '65a5093d6ffb9-pprt-76261375516426271', 'en', 'name', 'RoboTrex, Automation Window', '2024-01-15 17:30:21', '2024-01-15 17:30:21'),
(1954, 'App\\Models\\ProductPart', '65a5093d6ffb9-pprt-76261375516426271', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The automation window is used equally for the RoboTrex 52 and 96 automation systems. If the machine tool to be automated does not yet have a window for the desired side loading, this special automation window is inserted during the installation of the automation system.</p>', '2024-01-15 17:30:21', '2024-01-15 17:30:21'),
(1955, 'App\\Models\\ProductPart', '65a5093d6ffb9-pprt-76261375516426271', 'en', 'further_information', '<p><br></p>', '2024-01-15 17:30:21', '2024-01-15 17:30:21'),
(1956, 'App\\Models\\ProductPart', '65a509e180f6f-pprt-83315886353970083', 'en', 'name', 'RoboTrex 96, Positioning Bolt', '2024-01-15 17:33:05', '2024-01-15 17:33:05'),
(1957, 'App\\Models\\ProductPart', '65a509e180f6f-pprt-83315886353970083', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">This positioning bolt is a spare part for both versions of RoboTrex 96 automation trolleys, but can also be used for individual storage devises.</p>', '2024-01-15 17:33:05', '2024-01-15 17:33:05'),
