(1983, 'App\\Models\\ProductPart', '65a510c765eb6-pprt-32579408934764655', 'en', 'name', 'Makro•Grip® Ultra, Stamping Jaws', '2024-01-15 18:02:31', '2024-01-15 18:02:31'),
(1984, 'App\\Models\\ProductPart', '65a510c765eb6-pprt-32579408934764655', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">These high-end stamping jaws are specially designed for use with the Makro-Grip® Ultra stamping unit and are supplied without support bars. Depending on which jaws are mounted on the Makro-Grip® Ultra system, the user can freely decide whether to mount parallels with a clamping depth of 3 mm (item no. 41111-0308) or with a clamping depth of 5 mm (item no. 41111-0508). These are available separately.</p>', '2024-01-15 18:02:31', '2024-01-15 18:02:31'),
(1985, 'App\\Models\\ProductPart', '65a510c765eb6-pprt-32579408934764655', 'en', 'further_information', '<p><br></p>', '2024-01-15 18:02:31', '2024-01-15 18:02:31'),
(1986, 'App\\Models\\ProductPart', '65a5122487fdc-pprt-16329921193034497', 'en', 'name', 'Makro•Grip® Ultra, Parallels', '2024-01-15 18:08:20', '2024-01-15 18:08:20'),
(1987, 'App\\Models\\ProductPart', '65a5122487fdc-pprt-16329921193034497', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">These parallels with a thickness of 8 mm are especially suitable for pre-stamping large workpieces with the Makro-Grip® Ultra stamping unit. The clamping depth is 3 mm (suitable for clamping jaws with item no. 81483).</p>', '2024-01-15 18:08:20', '2024-01-15 18:08:20'),
(1988, 'App\\Models\\ProductPart', '65a5122487fdc-pprt-16329921193034497', 'en', 'further_information', '<p><br></p>', '2024-01-15 18:08:20', '2024-01-15 18:08:20'),
(1989, 'App\\Models\\ProductPart', '65a5189fabe1b-pprt-49343963496920412', 'en', 'name', 'Makro•Grip® Ultra, Parallels', '2024-01-15 18:35:59', '2024-01-15 18:35:59'),
(1990, 'App\\Models\\ProductPart', '65a5189fabe1b-pprt-49343963496920412', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">These parallels with a thickness of 8 mm are specially suitable for pre-stamping large workpieces with the Makro•Grip® Ultra stamping unit. The clamping depth is 5 mm (suitable for clamping jaws with item no. 81485).</p>', '2024-01-15 18:35:59', '2024-01-15 18:35:59'),
(1991, 'App\\Models\\ProductPart', '65a5189fabe1b-pprt-49343963496920412', 'en', 'further_information', '<p><br></p>', '2024-01-15 18:35:59', '2024-01-15 18:35:59'),
(1992, 'App\\Models\\ProductPart', '65a519e2280dd-pprt-66488020933185852', 'en', 'name', 'Makro•Grip® Ultra, Hexagon Socket', '2024-01-15 18:41:22', '2024-01-15 18:41:22');
INSERT INTO `translations` (`id`, `translatable_type`, `translatable_id`, `language_code`, `field`, `value`, `created_at`, `updated_at`) VALUES
(1993, 'App\\Models\\ProductPart', '65a519e2280dd-pprt-66488020933185852', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The hexagon socket size 19 mm can be used to clamp the workpieces in the Makro•Grip® Ultra clamping system. Its 1/2” square drive fits standard torque wrenches. The maximum tightening torque of the Makro•Grip® Ultra spindle unit is 170 Nm.</p>', '2024-01-15 18:41:22', '2024-01-15 18:41:22'),
(1994, 'App\\Models\\ProductPart', '65a519e2280dd-pprt-66488020933185852', 'en', 'further_information', '<p><br></p>', '2024-01-15 18:41:22', '2024-01-15 18:41:22'),
(1995, 'App\\Models\\ProductPart', '65a528fe44e90-pprt-81039581657713721', 'en', 'name', 'Makro•Grip® Ultra, Wrench', '2024-01-15 19:45:50', '2024-01-15 19:45:50'),
(1996, 'App\\Models\\ProductPart', '65a528fe44e90-pprt-81039581657713721', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The wrench with external hexagon and a size of 19 mm can be used for the initial clamping setting in the Makro•Grip® Ultra system. This wrench is already included in the scope of delivery of the Makro•Grip® Ultra base sets. However, the final clamping of the workpieces should be done with a torque wrench.</p>', '2024-01-15 19:45:50', '2024-01-15 19:45:50'),
(1997, 'App\\Models\\ProductPart', '65a528fe44e90-pprt-81039581657713721', 'en', 'further_information', '<p><br></p>', '2024-01-15 19:45:50', '2024-01-15 19:45:50'),
(1998, 'App\\Models\\ProductPart', '65a529ad59dc0-pprt-48237410740885293', 'en', 'name', 'Makro•Grip® Ultra, Hexagon Socket', '2024-01-15 19:48:45', '2024-01-15 19:48:45'),
(1999, 'App\\Models\\ProductPart', '65a529ad59dc0-pprt-48237410740885293', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The hexagon socket size 19 mm can be used to clamp the workpieces in the Makro•Grip® Ultra clamping system. Its 1/2” square drive fits standard torque wrenches. The maximum tightening torque of the Makro•Grip® Ultra spindle unit is 170 Nm.</p>', '2024-01-15 19:48:45', '2024-01-15 19:48:45'),
(2000, 'App\\Models\\ProductPart', '65a529ad59dc0-pprt-48237410740885293', 'en', 'further_information', '<p><br></p>', '2024-01-15 19:48:45', '2024-01-15 19:48:45'),
(2001, 'App\\Models\\ProductPart', '65a52a8cad121-pprt-88124379708574293', 'en', 'name', 'Makro•4Grip, Stamping Jaws', '2024-01-15 19:52:28', '2024-01-15 19:52:28'),
(2002, 'App\\Models\\ProductPart', '65a52a8cad121-pprt-88124379708574293', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The Makro•4Grip stamping jaws, which enable the pre-stamping of round blanks, are compatible with all versions of the stamping unit. Two stamping inserts are mounted on each Makro•4Grip stamping jaw, with which the workpiece is stamped. In order to adapt the stamping inserts to different workpiece diameters or clamping jaw sizes, the stamping inserts are positioned at a total of three possible distances (narrow, medium, wide) from each other.</p>', '2024-01-15 19:52:28', '2024-01-15 19:52:28'),
(2003, 'App\\Models\\ProductPart', '65a52a8cad121-pprt-88124379708574293', 'en', 'further_information', '<p><br></p>', '2024-01-15 19:52:28', '2024-01-15 19:52:28'),
(2004, 'App\\Models\\ProductPart', '65a52b8044cd4-pprt-20802779460938925', 'en', 'name', 'Makro•4Grip, Stamping Inserts', '2024-01-15 19:56:32', '2024-01-15 19:56:32'),
(2005, 'App\\Models\\ProductPart', '65a52b8044cd4-pprt-20802779460938925', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Round blanks are pre-stamped with the stamping inserts and then held with Makro•4Grip clamping jaws by form-fit. Four stamping inserts are required per pair of stamping jaws. Each stamping insert has a total of three cutting edges. If one cutting edge is worn out, two others can be used by turning them by 120 degrees and reassembling them.</p>', '2024-01-15 19:56:32', '2024-01-15 19:56:32'),
(2006, 'App\\Models\\ProductPart', '65a52b8044cd4-pprt-20802779460938925', 'en', 'further_information', '<p><br></p>', '2024-01-15 19:56:32', '2024-01-15 19:56:32'),
(2007, 'App\\Models\\ProductPart', '65a52c45a057e-pprt-76873471037803464', 'en', 'name', 'Hydro•Sup, Spacer', '2024-01-15 19:59:49', '2024-01-15 19:59:49'),
(2008, 'App\\Models\\ProductPart', '65a52c45a057e-pprt-76873471037803464', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">This spacer, in conjunction with the Hydro•Sup hydraulic screw jack, provides an additional support surface at a height of between 228 and 232 mm and is, therefore, suitable for the “L” system height of Makro•Grip® Ultra. Together with the Hydro•Sup, it serves to reduce possible vibrations in the machining process of protruding components.</p>', '2024-01-15 19:59:49', '2024-01-15 19:59:49'),
(2009, 'App\\Models\\ProductPart', '65a52c45a057e-pprt-76873471037803464', 'en', 'further_information', '<p><br></p>', '2024-01-15 19:59:49', '2024-01-15 19:59:49'),
(2010, 'App\\Models\\ProductPart', '65a52d56dc935-pprt-85562374145695831', 'en', 'name', 'Hydro•Sup, Spacer', '2024-01-15 20:04:22', '2024-01-15 20:04:22'),
(2011, 'App\\Models\\ProductPart', '65a52d56dc935-pprt-85562374145695831', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">This spacer, in conjunction with the Hydro•Sup hydraulic screw jack, provides an additional support surface at a height of between 148 and 152 mm and is, therefore, suitable for the “M” system height of Makro•Grip® Ultra. Together with the Hydro•Sup, it serves to reduce possible vibrations in the machining process of protruding components.</p>', '2024-01-15 20:04:22', '2024-01-15 20:04:22'),
(2012, 'App\\Models\\ProductPart', '65a52d56dc935-pprt-85562374145695831', 'en', 'further_information', '<p><br></p>', '2024-01-15 20:04:22', '2024-01-15 20:04:22'),
(2013, 'App\\Models\\ProductPart', '65a52e5f0d9da-pprt-72973285938758470', 'en', 'name', 'Hydro•Sup, Hydraulic Screw Jack', '2024-01-15 20:08:47', '2024-01-15 20:08:47'),
(2014, 'App\\Models\\ProductPart', '65a52e5f0d9da-pprt-72973285938758470', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The hydraulic screw jack Hydro•Sup serves to reduce possible vibrations in the machining process of protruding components. With a height of 86 mm, it matches the lowest system height of Makro•Grip® Ultra base body height. Due to its pendulum support, it offers a support height between 85 and 89 mm. By using additional spacers, the total height of the M and L systems can be replicated.</p>', '2024-01-15 20:08:47', '2024-01-15 20:08:47'),
(2015, 'App\\Models\\ProductPart', '65a52e5f0d9da-pprt-72973285938758470', 'en', 'further_information', '<p><br></p>', '2024-01-15 20:08:47', '2024-01-15 20:08:47'),
(2016, 'App\\Models\\ProductPart', '65a541e7becb2-pprt-76741314163955876', 'en', 'name', 'Makro•Grip® Ultra, Connection Plate', '2024-01-15 21:32:07', '2024-01-15 21:32:07'),
(2017, 'App\\Models\\ProductPart', '65a541e7becb2-pprt-76741314163955876', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Connection plates are needed to connect Makro-Grip® Ultra bodies together. They are attached to the rear base body and have a fit on the outside to accommodate a sliding block mounted on the outer end of the front base body. They are already included with the 610 and 810 Base Sets.</p>', '2024-01-15 21:32:07', '2024-01-15 21:32:07'),
(2018, 'App\\Models\\ProductPart', '65a541e7becb2-pprt-76741314163955876', 'en', 'further_information', '<p><br></p>', '2024-01-15 21:32:07', '2024-01-15 21:32:07'),
(2019, 'App\\Models\\ProductPart', '65a545804869e-pprt-31541056344043245', 'en', 'name', 'Makro•Grip® Ultra, Centering Plate', '2024-01-15 21:47:28', '2024-01-15 21:47:28'),
(2020, 'App\\Models\\ProductPart', '65a545804869e-pprt-31541056344043245', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Centring plates are used to provide a precise fit for the spindle unit of Makro-Grip® Ultra. Two centring plates are required per clamping unit, which are attached to the inner ends of the base bodies. This version is required for centric single part clamping and is included in the scope of delivery of the Base Sets.</p>', '2024-01-15 21:47:28', '2024-01-15 21:47:28'),
(2021, 'App\\Models\\ProductPart', '65a545804869e-pprt-31541056344043245', 'en', 'further_information', '<p><br></p>', '2024-01-15 21:47:28', '2024-01-15 21:47:28'),
(2022, 'App\\Models\\ProductPart', '65a5463d202de-pprt-13232862562592496', 'en', 'name', 'Makro•Grip® Ultra, Centering Plate', '2024-01-15 21:50:37', '2024-01-15 21:50:37'),
(2023, 'App\\Models\\ProductPart', '65a5463d202de-pprt-13232862562592496', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Centring plates are used to ensure a precise fit of the spindle unit of Makro-Grip® Ultra. Two centring plates are required per clamping unit, which are attached to the inner ends of the base bodies. This version is required for compensating multiple clamping and is characterised by a milled recess which gives the spindle unit additional clearance for components of different sizes (max. 4 mm).</p>', '2024-01-15 21:50:37', '2024-01-15 21:50:37'),
(2024, 'App\\Models\\ProductPart', '65a5463d202de-pprt-13232862562592496', 'en', 'further_information', '<p><br></p>', '2024-01-15 21:50:37', '2024-01-15 21:50:37'),
(2025, 'App\\Models\\ProductPart', '65a54c615aea4-pprt-60762083671876198', 'en', 'name', 'Makro•Grip® Ultra, Spindle Unit', '2024-01-15 22:16:49', '2024-01-15 22:16:49'),
(2026, 'App\\Models\\ProductPart', '65a54c615aea4-pprt-60762083671876198', 'en', 'key_features', '<p><div class=\"product-attributes__data-list\" style=\"box-sizing: inherit; margin-bottom: 36px; z-index: 1; position: relative; grid-column: 1 / 2; color: rgb(87, 87, 86); font-family: &quot;Encode Sans Compressed&quot;, sans-serif; font-size: 20px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: 0.8px; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(247, 247, 248); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div class=\"data__item\" style=\"box-sizing: inherit; padding: 0px; border-bottom: none; display: grid; grid-template-columns: 50% 50%; gap: 7px; font-size: 1rem;\"></div></div></p><p class=\"product__text\" style=\"box-sizing: inherit; margin: 0px 0px 36px; z-index: 1; position: relative; grid-column: 1 / 2; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">The spindle unit for the Makro•Grip® Ultra is simply fitted between two high-precision centering plates, which is why the system is set up very quickly. By removing the clamping jaws, the spindle unit can be removed upwards, which makes cleaning after (and between) production processes extremely easy and convenient.</p>', '2024-01-15 22:16:49', '2024-01-15 22:16:49'),
(2027, 'App\\Models\\ProductPart', '65a54c615aea4-pprt-60762083671876198', 'en', 'further_information', '<p><br></p>', '2024-01-15 22:16:49', '2024-01-15 22:16:49'),
