(2237, 'App\\Models\\Category', '65c3dd44d5c5e-ctgr-41625128716521496', 'en', 'title', 'Economy Clamps', '2024-02-08 02:43:00', '2024-02-08 02:43:00'),
(2238, 'App\\Models\\Product', '65c3e5614380f-prod-24864850000037499', 'en', 'name', 'OK-Vise-Economy-Clamps', '2024-02-08 03:17:37', '2024-02-08 03:17:37'),
(2239, 'App\\Models\\Product', '65c3e5614380f-prod-24864850000037499', 'en', 'key_features', '<p style=\"margin-block: 0px 0.9rem;\">The Cost-Efficient Choice.</p><p style=\"margin-block: 0px 0.9rem;\">In our economy workholding clamp models, only the bottom of the jaw is ground.</p><p style=\"margin-block: 0px 0.9rem;\">OK-VISE economy models are used in regular workholding when ultraprecision is not required.</p><p style=\"margin-block: 0px 0.9rem;\">They are made of the same raw materials as other models, and the bottom of the jaws is ground for precise positioning on the fixture base.</p><p style=\"margin-block: 0px 0.9rem;\">Our smallest series the “micro” clamp (size A) is only available as the economy model. The A-size clamp always comes with Viton O-rings.</p>', '2024-02-08 03:17:37', '2024-02-08 03:17:37'),
(2240, 'App\\Models\\Product', '65c3e5614380f-prod-24864850000037499', 'en', 'further_information', '<p><br></p>', '2024-02-08 03:17:37', '2024-02-08 03:17:37'),
(2241, 'App\\Models\\Product', '65c5006b984fc-prod-17627741172917088', 'en', 'name', 'OK-Vise-Economy-Clamps', '2024-02-08 23:25:15', '2024-02-08 23:25:15'),
(2242, 'App\\Models\\Product', '65c5006b984fc-prod-17627741172917088', 'en', 'key_features', '<p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248); margin-block: 0px 0.9rem;\">The Cost-Efficient Choice.</p><p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248); margin-block: 0px 0.9rem;\">In our economy workholding clamp models, only the bottom of the jaw is ground.</p><p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248); margin-block: 0px 0.9rem;\">OK-VISE economy models are used in regular workholding when ultraprecision is not required.</p><p style=\"color: rgb(82, 89, 111); font-family: Jost, sans-serif; letter-spacing: 0.024px; background-color: rgb(247, 247, 248); margin-block: 0px 0.9rem;\">They are made of the same raw materials as other models, and the bottom of the jaws is ground for precise positioning on the fixture base.</p>', '2024-02-08 23:25:15', '2024-02-08 23:25:15'),
