(2319, 'App\\Models\\Category', '65d76309a3a5d-ctgr-26282139225629367', 'en', 'title', 'Self Adjustable Clamps', '2024-02-22 22:06:49', '2024-02-22 22:06:49'),
(2320, 'App\\Models\\Product', '65d76bee4fe6a-prod-10738213731860297', 'en', 'name', 'OK-Vise Self Adjustable Clamping Model', '2024-02-22 22:44:46', '2024-02-22 22:44:46'),
(2321, 'App\\Models\\Product', '65d76bee4fe6a-prod-10738213731860297', 'en', 'key_features', '<p style=\"margin-block: 0px 0.9rem;\">Self-adjustable clamp model is a great option when the workpiece has irregular shapes.</p><p style=\"margin-block: 0px 0.9rem;\">These&nbsp;clamps have a self-adjustable ball pressure screw inserted&nbsp;into a clamp jaw.</p><p style=\"margin-block: 0px 0.9rem;\">The ball bearing at the end is made of steel and&nbsp;equipped with torsion protection, allowing the ball to self-adjust up&nbsp;to 9 degrees. This makes clamping irregular-shaped parts and castings&nbsp;more flexible.</p><p style=\"margin-block: 0px 0.9rem;\">Latest self-adjustable models (<font color=\"#121212\" face=\"Lato, sans-serif\"><span style=\"letter-spacing: -0.5px;\">-‘E’</span></font>) come with self-adjusting balls in both jaws.</p>', '2024-02-22 22:44:46', '2024-02-22 22:44:46'),
(2322, 'App\\Models\\Product', '65d76bee4fe6a-prod-10738213731860297', 'en', 'further_information', '<p><br></p>', '2024-02-22 22:44:46', '2024-02-22 22:44:46'),
(2323, 'App\\Models\\Product', '65d76e4951e0d-prod-66120495352770310', 'en', 'name', 'OK-Vise Self Adjustable Clamping Model', '2024-02-22 22:54:49', '2024-02-22 22:54:49'),
